    #[test]
    fn class_get_canonical_name_preserves_literal_dollar_in_member_name() {
        let mut ctx = mock_ctx();
        // A private VM identity (JIT round 21 wave 16, lane innerclasses: the
        // parallel-only flake). Every untouched mock reports identity 0, and
        // the mock's loader tables are `detached_loader_tables(0)`, one
        // instance for all of them. A test that registers a defining loader on
        // identity 0 (`classloader.rs`'s `test_builtin_find_loaded_class_*` /
        // `test_bare_url_class_loader_*`, which call
        // `register_defining_loader(detached_loader_tables(ctx.vm_identity()), ..)`)
        // latches `any_defining` for the rest of the process. The name bridges
        // then take the with-loaders arm, resolve the unlisted outer class
        // `org/apache/el/TesterFunctions` through `ensure_class_initialized`,
        // and the spoofed-member check refuses the pair (the outer class's own
        // `InnerClasses` is empty here): `IncompatibleClassChangeError`
        // instead of the name. Alone, the latch is clear and the no-loaders arm
        // answers. The (identity, class id) name caches are a second shared
        // table this keeps the test out of.
        ctx.set_vm_identity(0x7744_0003);
        let cid = ctx
            .ensure_class_initialized("org/apache/el/TesterFunctions$Inner$Class")
            .unwrap();
        ctx.set_inner_classes(
            cid,
            vec![(
                "org/apache/el/TesterFunctions$Inner$Class".to_string(),
                "org/apache/el/TesterFunctions".to_string(),
                "Inner$Class".to_string(),
                0,
            )],
        );
        let mirror = make_class_mirror(
            &mut ctx,
            cid.as_u32(),
            "org/apache/el/TesterFunctions$Inner$Class",
        );
        let result = native_class_get_canonical_name(&mut ctx, &[Value::Object(Some(mirror))]);
        let obj = match result.unwrap() {
            Some(Value::Object(Some(o))) => o,
            other => panic!("expected Object, got {other:?}"),
        };
        assert_eq!(
            ctx.read_string(obj).unwrap(),
            "org.apache.el.TesterFunctions.Inner$Class"
        );
        let result = native_class_get_simple_name(&mut ctx, &[Value::Object(Some(mirror))]);
        let obj = match result.unwrap() {
            Some(Value::Object(Some(o))) => o,
            other => panic!("expected Object, got {other:?}"),
        };
        assert_eq!(ctx.read_string(obj).unwrap(), "Inner$Class");
    }

    #[test]
    fn class_get_simple_name_top_level_with_literal_dollar_not_split() {
        // Dynamically-generated proxy classes (ByteBuddy/cglib/EasyMock) are
        // genuine TOP-LEVEL classes whose literal binary name happens to
        // contain `$` -- they have no `InnerClasses` attribute entry for
        // themselves. Real `Class.getSimpleName()` must NOT split on `$` in
        // this case (see jndirealmintegration-ldap-connection-npe residual:
        // EasyMock's `isAClassMock` does
        // `getSimpleName().contains("$$$EasyMock$")`, which silently broke
        // when this returned just the trailing digit).
        let mut ctx = mock_ctx();
        let cid = ctx
            .ensure_class_initialized("org/easymock/mocks/InitialDirContext$$$EasyMock$1")
            .unwrap();
        // No `set_inner_classes` call: default (empty) matches a real
        // top-level class with no InnerClasses entry.
        let mirror = make_class_mirror(
            &mut ctx,
            cid.as_u32(),
            "org/easymock/mocks/InitialDirContext$$$EasyMock$1",
        );
        let r = native_class_get_simple_name(&mut ctx, &[Value::Object(Some(mirror))]);
        let obj = match r.unwrap() {
            Some(Value::Object(Some(o))) => o,
            other => panic!("expected Object, got {other:?}"),
        };
        assert_eq!(
            ctx.read_string(obj).unwrap(),
            "InitialDirContext$$$EasyMock$1"
        );
    }

