    // -----------------------------------------------------------------------
    // Enum.valueOf refusal message
    // -----------------------------------------------------------------------

    /// The exact HotSpot text, including the dot before the constant.
    #[test]
    fn no_enum_constant_message_names_the_type() {
        assert_eq!(
            super::no_enum_constant_message("java.math.RoundingMode", "SIDEWAYS"),
            "No enum constant java.math.RoundingMode.SIDEWAYS"
        );
    }

    /// A NESTED enum must appear with a DOT, not the binary `$`. This is the
    /// case the differential probe exercises (`ShadowDifferentialProbe.Color`);
    /// building the message from `getName()` would emit
    /// `ShadowDifferentialProbe$Color.MAUVE`, which is a different divergence
    /// rather than a fix. Driven through the mirror path so it also covers
    /// `native_class_get_canonical_name`'s `$` -> `.` rewrite.
    #[test]
    fn no_enum_constant_message_uses_dots_for_a_nested_enum() {
        let mut ctx = mock_ctx();
        // `CANONICAL_CLASS_NAME_CACHE` is keyed on (vm_identity, class_id) and
        // every untouched mock reports identity 0, so tests that mint class ids
        // independently share one cache. Take a private identity rather than
        // race the rest of the module for id space.
        ctx.set_vm_identity(0x7744_0001);
        let cid = ctx
            .ensure_class_initialized("ShadowDifferentialProbe$Color")
            .unwrap();
        ctx.set_inner_classes(
            cid,
            vec![(
                "ShadowDifferentialProbe$Color".to_string(),
                "ShadowDifferentialProbe".to_string(),
                "Color".to_string(),
                0,
            )],
        );
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), "ShadowDifferentialProbe$Color");
        assert_eq!(
            super::no_enum_constant_message_for_mirror(&mut ctx, mirror, "MAUVE"),
            "No enum constant ShadowDifferentialProbe.Color.MAUVE"
        );
    }

    /// A local or anonymous enum has no canonical name; the JDK concatenates
    /// the resulting null into the message verbatim. Reproduced rather than
    /// papered over, because the point of the message is HotSpot parity.
    #[test]
    fn no_enum_constant_message_renders_a_null_canonical_name_as_null() {
        legacy_em_less_rows(|| {
        let mut ctx = mock_ctx();
        ctx.set_vm_identity(0x7744_0002);
        let cid = ctx.ensure_class_initialized("RReflect$2").unwrap();
        ctx.set_inner_classes(
            cid,
            vec![("RReflect$2".to_string(), String::new(), String::new(), 0)],
        );
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), "RReflect$2");
        assert_eq!(
            super::no_enum_constant_message_for_mirror(&mut ctx, mirror, "X"),
            "No enum constant null.X"
        );
        });
    }

    // -----------------------------------------------------------------------
    // Class.isSynthetic
    // -----------------------------------------------------------------------

    #[test]
    fn class_is_synthetic_reads_the_access_flag() {
        const ACC_SYNTHETIC: u16 = 0x1000;
        let mut ctx = mock_ctx();
        let cid = ctx.ensure_class_initialized("P3$SwitchMap").unwrap();
        // SAFETY: single-threaded test code (same pattern as the enum tests).
        unsafe {
            (*ctx.class_flags_override.get()).insert(cid.as_u32(), ACC_SYNTHETIC);
        }
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), "P3$SwitchMap");
        let r = native_class_is_synthetic(&mut ctx, &[Value::Object(Some(mirror))]);
        assert_eq!(r.unwrap(), Some(Value::Int(1)));
    }

    #[test]
    fn class_is_synthetic_false_for_an_ordinary_class() {
        let mut ctx = mock_ctx();
        let cid = ctx.ensure_class_initialized("P3").unwrap();
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), "P3");
        let r = native_class_is_synthetic(&mut ctx, &[Value::Object(Some(mirror))]);
        assert_eq!(r.unwrap(), Some(Value::Int(0)));
    }

    #[test]
    fn class_is_synthetic_prefers_the_inner_classes_flags_for_a_nested_class() {
        // JVMS 4.7.6 / JVM_GetClassModifiers: a nested class's modifiers come
        // from its `InnerClasses` entry, not its own ClassFile access_flags.
        // javac marks the synthetic switch-map holder there.
        const ACC_SYNTHETIC: u16 = 0x1000;
        let mut ctx = mock_ctx();
        let cid = ctx.ensure_class_initialized("P3$1").unwrap();
        ctx.set_inner_classes(
            cid,
            vec![(
                "P3$1".to_string(),
                String::new(),
                String::new(),
                ACC_SYNTHETIC,
            )],
        );
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), "P3$1");
        let r = native_class_is_synthetic(&mut ctx, &[Value::Object(Some(mirror))]);
        assert_eq!(r.unwrap(), Some(Value::Int(1)));
    }

    #[test]
    fn class_is_synthetic_false_for_primitives_and_arrays() {
        // JVM_GetClassModifiers synthesises PUBLIC|FINAL|ABSTRACT for a
        // primitive and <element access>|FINAL|ABSTRACT for an array; neither
        // carries ACC_SYNTHETIC, so an array of a synthetic class is not
        // itself synthetic.
        let mut ctx = mock_ctx();
        let cid = ctx.ensure_class_initialized("int").unwrap();
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), "int");
        let r = native_class_is_synthetic(&mut ctx, &[Value::Object(Some(mirror))]);
        assert_eq!(r.unwrap(), Some(Value::Int(0)));

        const ACC_SYNTHETIC: u16 = 0x1000;
        let elem = ctx.ensure_class_initialized("P3$SynthElem").unwrap();
        // SAFETY: single-threaded test code.
        unsafe {
            (*ctx.class_flags_override.get()).insert(elem.as_u32(), ACC_SYNTHETIC);
        }
        let arr = ctx.ensure_class_initialized("[LP3$SynthElem;").unwrap();
        let arr_mirror = make_class_mirror(&mut ctx, arr.as_u32(), "[LP3$SynthElem;");
        let r = native_class_is_synthetic(&mut ctx, &[Value::Object(Some(arr_mirror))]);
        assert_eq!(r.unwrap(), Some(Value::Int(0)));
    }

    // -----------------------------------------------------------------------
    // Class.isAnonymousClass / isLocalClass / isMemberClass
    //
    // These only *matter* under `synthetic-jdk` (real-JDK mode runs
    // `java.lang.Class`'s own bytecode, which is already correct), but they
    // are compiled unconditionally: the registration site is not gated.
    // -----------------------------------------------------------------------

    /// `(isAnonymousClass, isLocalClass, isMemberClass)` for a class whose own
    /// `InnerClasses` entry is `entry` (`None` = no entry of its own).
    fn nesting_predicates(name: &str, entry: Option<(&str, &str)>) -> (i32, i32, i32) {
        let mut ctx = mock_ctx();
        let cid = ctx.ensure_class_initialized(name).unwrap();
        if let Some((outer, inner_name)) = entry {
            ctx.set_inner_classes(
                cid,
                vec![(
                    name.to_string(),
                    outer.to_string(),
                    inner_name.to_string(),
                    0,
                )],
            );
        }
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), name);
        let args = [Value::Object(Some(mirror))];
        let flag = |r: MethodCallResult| match r.unwrap() {
            Some(Value::Int(v)) => v,
            other => panic!("expected Int, got {other:?}"),
        };
        (
            flag(native_class_is_anonymous_class(&mut ctx, &args)),
            flag(native_class_is_local_class(&mut ctx, &args)),
            flag(native_class_is_member_class(&mut ctx, &args)),
        )
    }

    #[test]
    fn class_nesting_predicates_anonymous() {
        legacy_em_less_rows(|| {
        // inner_name_index == 0 AND outer_class_info_index == 0.
        assert_eq!(nesting_predicates("P3$1", Some(("", ""))), (1, 0, 0));
        });
    }

    #[test]
    fn class_nesting_predicates_local() {
        legacy_em_less_rows(|| {
        // Named, but outer_class_info_index == 0.
        assert_eq!(
            nesting_predicates("P3$1Local", Some(("", "Local"))),
            (0, 1, 0)
        );
        });
    }

    #[test]
    fn class_nesting_predicates_member() {
        assert_eq!(
            nesting_predicates("P3$Member", Some(("P3", "Member"))),
            (0, 0, 1)
        );
    }

    #[test]
    fn class_nesting_predicates_top_level_and_generated() {
        // A genuine top-level class has no entry of its own...
        assert_eq!(nesting_predicates("P3", None), (0, 0, 0));
        // ...and neither does a generated class whose binary name merely
        // contains `$` (proxies, lambda hidden classes) -- it must NOT be
        // mistaken for a nested class.
        assert_eq!(nesting_predicates("P3$$Lambda/0x80000000", None), (0, 0, 0));
    }

    #[test]
    fn class_nesting_predicates_arrays_are_never_nested() {
        // HotSpot reports false for all three on an array even when the
        // COMPONENT is a member/anonymous class.
        assert_eq!(
            nesting_predicates("[LP3$Member;", Some(("P3", "Member"))),
            (0, 0, 0)
        );
        assert_eq!(nesting_predicates("[LP3$1;", Some(("", ""))), (0, 0, 0));
    }

    // -----------------------------------------------------------------------
    // JIT round 21 wave 16, lane innerclasses
    // (`CRATONVM_DECLARING_CLASS_ANY_OUTER_ROW`; page
    // `r21-review-w15-native-findings-FIXED-20261020.md` item 9): a self row with an
    // outer class is a member link, named or not, and the first self row
    // decides (HotSpot `find_inner_classes_attr` / `compute_enclosing_class`).
    // -----------------------------------------------------------------------

    fn r21w16_rows<'a>(
        rows: &'a [(&'a str, &'a str, &'a str)],
    ) -> impl Iterator<Item = (&'a str, &'a str, &'a str)> + 'a {
        rows.iter().copied()
    }

    #[test]
    fn r21w16_unnamed_row_with_outer_is_a_member_link() {
        let rows = [("p/Outer$1", "p/Outer", "")];
        assert_eq!(
            super::declaring_member_row_outer(r21w16_rows(&rows), "p/Outer$1", true),
            Some("p/Outer")
        );
        // `=0`: the old rule wanted a simple name too.
        assert_eq!(
            super::declaring_member_row_outer(r21w16_rows(&rows), "p/Outer$1", false),
            None
        );
    }

    #[test]
    fn r21w16_named_member_local_and_anonymous_rows_keep_their_answers() {
        for any in [true, false] {
            let member = [("p/O$I", "p/O", "I")];
            assert_eq!(
                super::declaring_member_row_outer(r21w16_rows(&member), "p/O$I", any),
                Some("p/O")
            );
            let local = [("p/O$1L", "", "L")];
            assert_eq!(super::declaring_member_row_outer(r21w16_rows(&local), "p/O$1L", any), None);
            let anonymous = [("p/O$1", "", "")];
            assert_eq!(super::declaring_member_row_outer(r21w16_rows(&anonymous), "p/O$1", any), None);
            // Rows of other classes never count.
            let others = [("p/O$X", "p/O", "X"), ("p/O", "", "")];
            assert_eq!(super::declaring_member_row_outer(r21w16_rows(&others), "p/O$Y", any), None);
        }
    }

    #[test]
    fn r21w16_first_self_row_decides() {
        // HotSpot stops at the first row naming the class; a later member row
        // is never read. The old rule searched on.
        let rows = [("p/O$1", "", ""), ("p/O$1", "p/O", "One")];
        assert_eq!(super::declaring_member_row_outer(r21w16_rows(&rows), "p/O$1", true), None);
        assert_eq!(
            super::declaring_member_row_outer(r21w16_rows(&rows), "p/O$1", false),
            Some("p/O")
        );
        let rows = [("p/O$1", "p/O", ""), ("p/O$1", "p/Q", "One")];
        assert_eq!(
            super::declaring_member_row_outer(r21w16_rows(&rows), "p/O$1", true),
            Some("p/O")
        );
    }

    /// `row_nesting_kind`, which also decides `canonical_class_name` (only a
    /// Member has a canonical name). Arguments: outer empty, name empty,
    /// `EnclosingMethod` present, switch on.
    #[test]
    fn r21w16_row_nesting_kind_follows_enclosing_method() {
        use super::NestingKind as N;
        // Wave 16/17 answers: `CRATONVM_COMPAT_NESTING_FOLLOWS_ENCLOSING_METHOD` off.
        let k = |o, n, em, any| super::row_nesting_kind(o, n, em, any, false);
        // Switch on, HotSpot's answers.
        assert!(k(false, false, true, true) == N::Local); // named, outer, EM: local
        assert!(k(false, true, true, true) == N::Anonymous); // unnamed, outer, EM
        assert!(k(true, false, true, true) == N::Local);
        assert!(k(true, true, true, true) == N::Anonymous);
        assert!(k(false, true, false, true) == N::Member); // unnamed, outer, no EM
        assert!(k(false, false, false, true) == N::Member);
        // javac's local/anonymous rows read the same without EM in the fixture.
        assert!(k(true, false, false, true) == N::Local);
        assert!(k(true, true, false, true) == N::Anonymous);
        // Switch off: the old row-shape rule, EM ignored.
        assert!(k(false, false, true, false) == N::Member);
        assert!(k(false, true, false, false) == N::Anonymous);
        assert!(k(true, false, false, false) == N::Local);
    }

    // -----------------------------------------------------------------------
    // JIT round 21 wave 19, lane innerclasses (page
    // `r21-review-w18-findings-FIXED-20261020.md` items 2, 3, 4, 7).
    // -----------------------------------------------------------------------

    /// The mock has no `EnclosingMethod`, so its javac-shaped local and
    /// anonymous rows are top level to JDK 25 once
    /// `CRATONVM_COMPAT_NESTING_FOLLOWS_ENCLOSING_METHOD` is on (item 3). The
    /// tests written for those shapes run with it off, in a thread scope.
    fn legacy_em_less_rows<R>(f: impl FnOnce() -> R) -> R {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_COMPAT_NESTING_FOLLOWS_ENCLOSING_METHOD", Some("0"))],
            f,
        )
    }

    /// Item 3: JDK 25's kinds (`isLocalOrAnonymousClass` is
    /// `hasEnclosingMethodInfo`). Arguments: outer empty, name empty,
    /// `EnclosingMethod` present, any-outer-row switch, EM switch.
    #[test]
    fn r21w19_nesting_kind_follows_enclosing_method() {
        use super::NestingKind as N;
        let k = |o, n, em| super::row_nesting_kind(o, n, em, true, true);
        // A self row with no outer class and no EM is top level (X$2, X$5).
        assert!(k(true, true, false) == N::TopLevel);
        assert!(k(true, false, false) == N::TopLevel);
        // EM decides local or anonymous whatever the row's outer class.
        assert!(k(true, true, true) == N::Anonymous);
        assert!(k(true, false, true) == N::Local);
        assert!(k(false, false, true) == N::Local);
        // An outer class without EM is a member, named or not.
        assert!(k(false, false, false) == N::Member);
        assert!(k(false, true, false) == N::Member);
        // No row: EM makes it anonymous (X$4); else top level.
        assert!(super::no_row_nesting_kind(true, true) == N::Anonymous);
        assert!(super::no_row_nesting_kind(false, true) == N::TopLevel);
        assert!(super::no_row_nesting_kind(true, false) == N::TopLevel);
    }

    /// Item 3 through the bridges: a self row with no outer class and no
    /// `EnclosingMethod` (X$2 / X$5 of `R21Fz6InnerRows1`) is top level, so
    /// the simple name is the binary-name tail and the canonical name is
    /// `getName()`, and no nesting predicate holds.
    #[test]
    fn r21w19_row_without_outer_or_enclosing_method_is_top_level() {
        let mut ctx = mock_ctx();
        if !super::nesting_follows_enclosing_method_enabled(&ctx)
            || !super::declaring_class_any_outer_row_enabled(&ctx)
        {
            return;
        }
        ctx.set_vm_identity(0x7744_0019);
        let cid = ctx.ensure_class_initialized("r21fz6/X$5").unwrap();
        ctx.set_inner_classes(
            cid,
            vec![("r21fz6/X$5".to_string(), String::new(), "Loc".to_string(), 0)],
        );
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), "r21fz6/X$5");
        let r = native_class_get_simple_name(&mut ctx, &[Value::Object(Some(mirror))]);
        let obj = match r.unwrap() {
            Some(Value::Object(Some(o))) => o,
            other => panic!("expected Object, got {other:?}"),
        };
        assert_eq!(ctx.read_string(obj).unwrap(), "X$5");
        let r = native_class_get_canonical_name(&mut ctx, &[Value::Object(Some(mirror))]);
        let obj = match r.unwrap() {
            Some(Value::Object(Some(o))) => o,
            other => panic!("expected Object, got {other:?}"),
        };
        assert_eq!(ctx.read_string(obj).unwrap(), "r21fz6.X$5");
        assert_eq!(nesting_predicates("r21fz6/X$2", Some(("", ""))), (0, 0, 0));
    }

    /// Item 2: the first self row decides in the `Lookup.in` walk and the
    /// `getEnclosingClass` bridge too; the member rule has one copy.
    #[test]
    fn r21w19_member_rule_has_one_copy() {
        let walk = include_str!("classloader.rs");
        let at = walk.find("\nfn lk_outermost_enclosing(").expect("the Lookup.in walk");
        let body = &walk[at..];
        let body = &body[..body.find("\n}\n").expect("its end")];
        assert!(body.contains("crate::lang_class::member_row_outer_of("));
        assert!(!body.contains("inner == &name && !outer.is_empty()"));
        let reflect = include_str!("lang_reflect.rs");
        assert!(reflect.contains("crate::lang_class::member_row_outer_of(&*ctx, &entries, &this_name)"));
        assert!(!reflect.contains("inner == &this_name && !outer.is_empty()"));
        // X$6: `[(C, -, -), (C, O, "N")]` with no EM has no member link.
        let rows = [("C", "", ""), ("C", "O", "N")];
        assert_eq!(
            super::declaring_member_row_outer(rows.iter().copied(), "C", true),
            None
        );
    }

    /// Item 4: a fill guard taken before a redefinition's forget does not
    /// keep its answer. Mocks have no cache slot, so the guard is inert there
    /// (`None`), and the insert stands.
    #[test]
    fn r21w19_fill_guard_is_inert_without_a_cache_slot() {
        let ctx = mock_ctx();
        ctx.set_vm_identity(0x7744_001A);
        let fill = super::inner_tables_fill_guard(&ctx);
        assert!(!fill.moved(&ctx));
        let cid = ClassId::new(0x0019_0001);
        let kept = super::cache_insert_inner_tables(
            &super::SIMPLE_CLASS_NAME_CACHE,
            &ctx,
            cid,
            Arc::from("N"),
            fill,
        );
        assert_eq!(&*kept, "N");
        assert_eq!(
            super::cache_get(&super::SIMPLE_CLASS_NAME_CACHE, 0x7744_001A, cid).as_deref(),
            Some("N")
        );
        super::forget_vm_class_name_caches(0x7744_001A);
    }

    /// Item 4: the order the guard relies on. The forget bumps the generation
    /// before it clears, and every fill takes its guard first and re-reads the
    /// generation after its insert (source pins).
    #[test]
    fn r21w19_forget_bumps_before_it_clears_and_fills_are_guarded() {
        let src = include_str!("lang_class.rs");
        let at = src
            .find("\npub fn forget_redefined_inner_class_answers(")
            .expect("the forget");
        let body = &src[at..];
        let body = &body[..body.find("\n}\n").expect("its end")];
        let bump = body.find("inner_tables_generation").expect("the bump");
        let clear = body.find("spoof_verdicts.write().clear()").expect("the clear");
        assert!(bump < clear, "the generation must move before the clear");
        for fill in ["\nfn resolve_simple_name(", "\npub(crate) fn canonical_class_name(", "\nfn spoof_verdict_memo("] {
            let at = src.find(fill).expect(fill);
            let body = &src[at..];
            let body = &body[..body.find("\n}\n").expect("its end")];
            assert!(body.contains("inner_tables_fill_guard("), "{fill} takes a guard");
        }
    }

    /// JIT round 21 wave 24, lane names (`r21-optin-flip-review-FIXED-20261021.md`
    /// #13): an id-less mirror's answer is noted only once a per-VM strong
    /// hold exists for it. Failed before: the note took any interned answer,
    /// which only the weak intern table held.
    #[test]
    fn r21w24_mirror_memo_notes_only_strongly_held_idless_answers() {
        use cratonvm_native_api::NativeHeapAccess;
        let mut ctx = crate::test_utils::mock_ctx();
        let a = ctx.create_string("[I");
        let b = ctx.create_string("[I");
        // A mock has no per-VM slot: nothing can hold the answer, so no note.
        assert!(!super::class_get_name_hold_idless_answer(&mut ctx, a));
        let slot: std::sync::OnceLock<Box<dyn std::any::Any + Send + Sync>> =
            std::sync::OnceLock::new();
        let caches = (**slot.get_or_init(super::new_reflect_door_caches))
            .downcast_ref::<super::ReflectDoorCaches>()
            .expect("door caches");
        let holds = &caches.class_names_idless;
        assert_eq!(super::class_get_name_idless_hold_lookup(holds, &ctx, "[I", a), None);
        let handle = ctx.add_global_root(a);
        assert!(super::class_get_name_idless_hold_insert(holds, "[I", handle).is_ok());
        assert_eq!(ctx.resolve_global_root(handle), Some(a), "the hold is a strong root");
        assert_eq!(super::class_get_name_idless_hold_lookup(holds, &ctx, "[I", a), Some(true));
        // Another object for the same text is not the held answer: decline.
        assert_eq!(super::class_get_name_idless_hold_lookup(holds, &ctx, "[I", b), Some(false));
        // A racing second fill keeps the first hold.
        let other = ctx.add_global_root(b);
        assert_eq!(super::class_get_name_idless_hold_insert(holds, "[I", other), Err(handle));
        assert_eq!(holds.read().len(), 1);
    }

    /// Wave 21, item 6a: the unload sweep drops the dead classes' recorded
    /// resolution failures and the spoof verdicts that name them; live rows
    /// stay.
    #[test]
    fn r21w21_unload_forgets_dead_reflect_door_rows() {
        let slot: std::sync::OnceLock<Box<dyn std::any::Any + Send + Sync>> =
            std::sync::OnceLock::new();
        let caches = (**slot.get_or_init(super::new_reflect_door_caches))
            .downcast_ref::<super::ReflectDoorCaches>()
            .expect("door caches");
        let row = || super::RecordedResolutionFailure {
            class: Box::from("java/lang/NoClassDefFoundError"),
            message: Some(Box::from("p/Gone")),
            cause: None,
        };
        {
            let mut failures = caches.outer_resolution_failures.write();
            failures.insert((7, Box::from("p/Gone")), row());
            failures.insert((8, Box::from("p/Gone")), row());
        }
        {
            let mut verdicts = caches.spoof_verdicts.write();
            verdicts.insert((7u64 << 32) | 9, None); // dead inner
            verdicts.insert((9u64 << 32) | 7, None); // dead outer
            verdicts.insert((7u64 << 32) | super::SPOOF_BY_INNER, None); // dead, by inner
            verdicts.insert((8u64 << 32) | super::SPOOF_BY_INNER, None); // live
            verdicts.insert((8u64 << 32) | 9, None); // live pair
        }
        super::forget_unloaded_reflect_door_rows(&slot, &|id| id == 7);
        let failures = caches.outer_resolution_failures.read();
        assert!(!failures.contains_key(&(7, Box::from("p/Gone"))));
        assert!(failures.contains_key(&(8, Box::from("p/Gone"))));
        drop(failures);
        let verdicts = caches.spoof_verdicts.read();
        assert_eq!(verdicts.len(), 2, "only the live rows stay: {:?}", verdicts.keys());
        assert!(verdicts.contains_key(&((8u64 << 32) | super::SPOOF_BY_INNER)));
        assert!(verdicts.contains_key(&((8u64 << 32) | 9)));
        // A slot never filled has nothing to drop.
        let empty: std::sync::OnceLock<Box<dyn std::any::Any + Send + Sync>> =
            std::sync::OnceLock::new();
        super::forget_unloaded_reflect_door_rows(&empty, &|_| true);
        assert!(empty.get().is_none());
    }

    /// Wave 21, item 6b: the record-component descriptor path takes the
    /// unrecorded door, and every `klass_at` caller keeps the recorded one
    /// (source pins).
    #[test]
    fn r21w21_descriptor_types_are_not_recorded() {
        let src = include_str!("lang_class.rs");
        // Wave 22, lane hidden-resid (item 5 of
        // `r21-review-w22-findings-FIXED-20261020.md`): searched in the body of
        // `getRecordComponents` only, with needles this test's own text
        // cannot match, so the pin fails if the descriptor type goes back
        // to the recorded door.
        let at = src
            .find("\npub(crate) fn native_class_get_record_components(")
            .expect("getRecordComponents");
        let record_components = &src[at..];
        let record_components =
            &record_components[..record_components.find("\n}\n").expect("its end")];
        assert!(record_components.contains(concat!(
            "match class_seen_by_referencing_class",
            "_unrecorded(ctx, class_id, inner) {"
        )));
        assert!(!record_components.contains(concat!(
            "class_seen_by_referencing_class",
            "_checked("
        )));
        let at = src
            .find("\npub(crate) fn class_seen_by_referencing_class_checked(")
            .expect("the recorded door");
        let body = &src[at..];
        let body = &body[..body.find("\n}\n").expect("its end")];
        assert!(body.contains("recorded_outer_resolution_failure(ctx, referencing, name)"));
        assert!(body.contains("record_outer_resolution_failure(ctx, referencing, name, failed)"));
    }

    /// JIT round 21 wave 26, lane reserr: [`super::failure_recorded_in`]
    /// answers exactly the recorded `(class, name)` rows.
    #[test]
    fn r21w26_failure_recorded_in_reads_the_row() {
        let slot: std::sync::OnceLock<Box<dyn std::any::Any + Send + Sync>> =
            std::sync::OnceLock::new();
        let caches = (**slot.get_or_init(super::new_reflect_door_caches))
            .downcast_ref::<super::ReflectDoorCaches>()
            .expect("door caches");
        assert!(!super::failure_recorded_in(caches, 7, "p/Gone"), "empty table");
        caches.outer_resolution_failures.write().insert(
            (7, Box::from("p/Gone")),
            super::RecordedResolutionFailure {
                class: Box::from("java/lang/NoClassDefFoundError"),
                message: Some(Box::from("p/Gone")),
                cause: None,
            },
        );
        if caches.outer_resolution_failure_sticky {
            assert!(super::failure_recorded_in(caches, 7, "p/Gone"));
        }
        assert!(!super::failure_recorded_in(caches, 8, "p/Gone"), "another class");
        assert!(!super::failure_recorded_in(caches, 7, "p/Other"), "another name");
    }

    /// JIT round 21 wave 26, lane reserr (`R21Fz6LookupInLoad1`, source pin:
    /// mocks have no cache slot): the loader-aware declaring-class step asks
    /// the recorded door before its bare `loadClass`, and the slow path does
    /// not load an entry whose resolution already failed.
    #[test]
    fn r21w26_declaring_class_steps_consult_the_recorded_door() {
        let src = include_str!("lang_class.rs");
        let at = src
            .find("\nfn declaring_class_loader_aware(")
            .expect("the loader-aware step");
        let body = &src[at..];
        let body = &body[..body.find("\n}\n").expect("its end")];
        let door = body
            .find(concat!("class_seen_by_referencing_class", "_checked(ctx, class_id, &outer_class)"))
            .expect("the recorded door");
        let bare = body
            .find(concat!("load_class_named", "_as_the_vm("))
            .expect("the switch-off arm");
        assert!(door < bare, "the recorded door answers first");
        let at = src
            .find("\npub(crate) fn declaring_class_id_checked(")
            .expect("getDeclaringClass0's lookup");
        let body = &src[at..];
        let body = &body[..body.find("\n}\n").expect("its end")];
        assert!(body.contains(concat!("None if failed", "_before => None,")));
    }

