    /// JIT round 22 wave 1, lane review (item 1 of
    /// `docs/feature-designs/native-dispatch-architecture.md`): with a
    /// per-VM cache slot (the mock's opt-in one), a class-id mirror's fill is
    /// FILED under a global root (the `held` decision of
    /// `native_class_get_name_memoizing`), a refill replaces the row and
    /// releases the old root, and an id-less answer is held once per text:
    /// the same object again is held, another object of that text is not.
    /// Without a slot nothing is held.
    #[test]
    fn r22_get_name_memo_fill_and_idless_hold_with_a_cache_slot() {
        let mut ctx = mock_ctx();
        ctx.enable_reflect_door_cache_slot();
        ctx.ensure_class_initialized("java/lang/Object").unwrap();
        let cid = ctx.ensure_class_initialized("r22/Named").unwrap();
        let mirror = ctx.get_class_mirror(cid);
        assert_eq!(ctx.class_id_from_mirror(mirror), Some(cid));
        let name = ctx.create_string("r22.Named");
        let this_pin = ctx.pin_native_root(mirror);
        let name_pin = ctx.pin_native_root(name);
        assert!(super::class_get_name_memo_fill(&mut ctx, this_pin, mirror, name_pin, name), "filed");
        let row = |ctx: &crate::test_utils::MockNativeContext| {
            super::reflect_door_caches(ctx)
                .and_then(|c| c.class_names.read().get(&cid.as_u32()).copied())
        };
        let first = row(&ctx).expect("a row for the class id");
        assert!(ctx.resolve_global_root(first).is_some(), "its root holds the answer");
        assert!(super::class_get_name_memo_fill(&mut ctx, this_pin, mirror, name_pin, name), "refilled");
        let second = row(&ctx).expect("still a row");
        assert_ne!(first, second);
        assert!(ctx.resolve_global_root(first).is_none(), "the replaced root is released");
        ctx.unpin_native_roots(this_pin);

        let text = ctx.create_string("[Lr22.Named;");
        assert!(super::class_get_name_hold_idless_answer(&mut ctx, text), "held");
        assert!(super::class_get_name_hold_idless_answer(&mut ctx, text), "held already");
        let other = ctx.create_string("[Lr22.Named;");
        assert_ne!(other, text);
        assert!(
            !super::class_get_name_hold_idless_answer(&mut ctx, other),
            "another object of the same text is not held"
        );

        let mut bare = mock_ctx();
        let t = bare.create_string("[I");
        assert!(!super::class_get_name_hold_idless_answer(&mut bare, t), "no slot: nothing held");
    }

    /// JIT round 21 wave 25, lane hexname (item 5 of
    /// `r21-review-w23-findings-FIXED-20261020.md`, probe `R21Fz9ReviewHexName1`;
    /// `CRATONVM_CLASS_NAME_HIDDEN_BY_CLASS`): an ORDINARY class whose last
    /// segment is `0x2A` is named `fz9.0x2A` / simple `0x2A`, as on HotSpot; a
    /// hidden class keeps its tail; an id that names another class keeps the
    /// shape rule. Failed before: `getName()` answered `fz9/0x2A` and
    /// `getSimpleName()` `fz9/0x2A` (the name's shape decided).
    #[test]
    fn r21w25_a_hex_tail_is_hidden_only_for_a_hidden_class() {
        if !super::class_name_hidden_by_class_enabled() {
            return;
        }
        let mut ctx = mock_ctx();
        ctx.set_vm_identity(0x7744_0025);
        let plain = ctx.ensure_class_initialized("r21w25/0x2A").unwrap();
        let hidden = ctx.ensure_class_initialized("r21w25/H/0x1f").unwrap();
        ctx.set_class_hidden(hidden);
        let d = |id, n: &str| super::dotted_binary_name_of_class(&ctx, Some(id), n);
        assert_eq!(d(plain, "r21w25/0x2A"), "r21w25.0x2A");
        assert_eq!(d(plain, "[Lr21w25/0x2A;"), "[Lr21w25.0x2A;");
        assert_eq!(d(hidden, "r21w25/H/0x1f"), "r21w25.H/0x1f");
        assert_eq!(d(hidden, "[Lr21w25/H/0x1f;"), "[Lr21w25.H/0x1f;");
        // A mismatched id never picks the flag: the shape rule.
        assert_eq!(d(hidden, "r21w25/0x2A"), "r21w25/0x2A");
        assert_eq!(super::dotted_binary_name_of_class(&ctx, None, "r21w25/0x2A"), "r21w25/0x2A");
        assert_eq!(&*super::top_level_simple_name_of_class(&ctx, plain, "r21w25/0x2A"), "0x2A");
        assert_eq!(&*super::top_level_simple_name_of_class(&ctx, hidden, "r21w25/H/0x1f"), "H/0x1f");
    }

    /// JIT round 21 wave 22, lane hidden-resid (item 1 of
    /// `r21-review-w22-findings-FIXED-20261020.md`): a class with `EnclosingMethod`
    /// skips the declaring-class checks but still resolves its EnclosingMethod
    /// class (`hasEnclosingMethodInfo`), in both bridges; a hidden class in
    /// the canonical bridge does not (`isHidden()` first). The mock resolves
    /// every name, so the error itself is pinned by source; the behaviour
    /// half checks that a resolvable EnclosingMethod class answers as before.
    #[test]
    fn r21w22_name_bridges_resolve_the_enclosing_method_class() {
        let mut ctx = mock_ctx();
        if !super::nesting_follows_enclosing_method_enabled(&ctx) {
            return;
        }
        ctx.set_vm_identity(0x7744_0022);
        let _host = ctx.ensure_class_initialized("r21w22/Host").unwrap();
        let name = "r21w22/Host$1Local";
        let cid = ctx.ensure_class_initialized(name).unwrap();
        ctx.set_inner_classes(
            cid,
            vec![(name.to_string(), String::new(), "Local".to_string(), 0)],
        );
        ctx.set_enclosing_method(cid, "r21w22/Host", "run", "()V");
        let mirror = make_class_mirror(&mut ctx, cid.as_u32(), name);
        assert!(!super::name_bridge_asks_declaring_class(&mut ctx, mirror, false));
        assert!(super::name_bridge_enclosing_method_error(
            &mut ctx,
            mirror,
            false,
            &super::SIMPLE_CLASS_NAME_CACHE
        )
        .is_none());
        let r = native_class_get_simple_name(&mut ctx, &[Value::Object(Some(mirror))]);
        let obj = match r.unwrap() {
            Some(Value::Object(Some(o))) => o,
            other => panic!("expected Object, got {other:?}"),
        };
        assert_eq!(ctx.read_string(obj).unwrap(), "Local");

        // Source: both bridges ask it exactly where they skip the checks, and
        // it resolves through the recorded door, after the hidden exit.
        let src = include_str!("lang_class.rs");
        let call = concat!("name_bridge_enclosing", "_method_error(ctx, this, ");
        for (bridge, kind) in [
            ("\npub(crate) fn native_class_get_simple_name(", "false"),
            ("\npub(crate) fn native_class_get_canonical_name(", "true"),
        ] {
            let at = src.find(bridge).expect(bridge);
            let body = &src[at..];
            let body = &body[..body.find("\n}\n").expect("its end")];
            let skip = body.find("    } else if let Some(failed) =").expect("the skip arm");
            let asked = body.find(&format!("{call}{kind}")).expect("asks it");
            assert!(skip < asked, "{bridge}");
        }
        let at = src.find("\nfn name_bridge_enclosing_method_error(").expect("the fn");
        let body = &src[at..];
        let body = &body[..body.find("\n}\n").expect("its end")];
        let hidden = body.find("canonical && ctx.is_class_hidden(element)").expect("hidden first");
        let resolve = body
            .find("class_seen_by_referencing_class_checked(ctx, element, &em_class)")
            .expect("the recorded door");
        assert!(hidden < resolve);
    }

    /// JIT round 21 wave 26, lane nesting
    /// (`CRATONVM_CLASS_LOCAL_INNER_CLASSES_CHECK`): HotSpot's
    /// `check_for_inner_class` with `inner_is_member` false. A local class
    /// its EnclosingMethod class does not list is an ICCE out of
    /// `getDeclaringClass0`; one it lists is null; a hidden one always
    /// disagrees; a member row or no row is not this arm.
    #[test]
    fn r21w26_local_class_must_be_listed_by_its_enclosing_class() {
        let row = |i: &str, o: &str, n: &str| (i.to_string(), o.to_string(), n.to_string(), 0u16);
        let msg = "r21w26.Host and r21w26.Host$1L disagree on InnerClasses attribute";
        assert_eq!(
            super::local_class_disagreement_text("r21w26/Host$1L", "r21w26/Host", false, &[])
                .as_deref(),
            Some(msg)
        );
        assert!(super::local_class_disagreement_text(
            "r21w26/Host$1L",
            "r21w26/Host",
            false,
            &[row("r21w26/Host$1L", "", "L")]
        )
        .is_none());
        // Listed as a MEMBER of the host: not the local arm's row.
        assert!(super::local_class_disagreement_text(
            "r21w26/Host$1L",
            "r21w26/Host",
            false,
            &[row("r21w26/Host$1L", "r21w26/Host", "L")]
        )
        .is_some());
        // Hidden: no table lists the hidden name; the external name keeps `/0x`.
        assert_eq!(
            super::local_class_disagreement_text(
                "r21w26/HLoc/0x1f",
                "r21w26/Host",
                true,
                &[row("r21w26/HLoc/0x1f", "", "HLoc")]
            )
            .as_deref(),
            Some("r21w26.Host and r21w26.HLoc/0x1f disagree on InnerClasses attribute")
        );

        if !super::class_local_inner_classes_check_enabled()
            || !super::class_inner_classes_check_enabled()
        {
            return;
        }
        let mut ctx = mock_ctx();
        let host = ctx.ensure_class_initialized("r21w26/Host").unwrap();
        let name = "r21w26/Host$1L";
        let cid = ctx.ensure_class_initialized(name).unwrap();
        ctx.set_inner_classes(cid, vec![row(name, "", "L")]);
        ctx.set_enclosing_method(cid, "r21w26/Host", "run", "()V");
        assert_eq!(
            super::local_class_inner_classes_disagreement(&mut ctx, cid).as_deref(),
            Some(msg)
        );
        ctx.set_inner_classes(host, vec![row(name, "", "L")]);
        assert!(super::local_class_inner_classes_disagreement(&mut ctx, cid).is_none());
        // No self row: `compute_enclosing_class` never reads EnclosingMethod.
        ctx.set_inner_classes(host, Vec::new());
        ctx.set_inner_classes(cid, Vec::new());
        assert!(super::local_class_inner_classes_disagreement(&mut ctx, cid).is_none());
    }

