    /// JIT round 21 wave 17 (`CRATONVM_REDEFINE_SWAPS_INNER_CLASSES`): a
    /// redefinition drops the VM's names built from the old tables (every
    /// class's, since a member's canonical name embeds its outer class's) and
    /// the redefined class's modifiers; another VM's rows stay.
    #[test]
    fn r21w17_redefinition_forgets_inner_class_answers_of_its_vm_only() {
        let ctx = mock_ctx();
        ctx.set_vm_identity(0x7744_0017);
        let redefined = ClassId::new(0x0017_0001);
        let member = ClassId::new(0x0017_0002);
        let other_vm = 0x7744_0018;
        super::cache_insert(&super::SIMPLE_CLASS_NAME_CACHE, 0x7744_0017, redefined, Arc::from("A"));
        super::cache_insert(&super::CANONICAL_CLASS_NAME_CACHE, 0x7744_0017, member, Arc::from("p.O.M"));
        super::cache_insert(&super::CANONICAL_CLASS_NAME_CACHE, other_vm, member, Arc::from("q.O.M"));
        super::forget_redefined_inner_class_answers(&ctx, redefined);
        assert!(super::cache_get(&super::SIMPLE_CLASS_NAME_CACHE, 0x7744_0017, redefined).is_none());
        assert!(super::cache_get(&super::CANONICAL_CLASS_NAME_CACHE, 0x7744_0017, member).is_none());
        assert_eq!(
            super::cache_get(&super::CANONICAL_CLASS_NAME_CACHE, other_vm, member).as_deref(),
            Some("q.O.M")
        );
        super::forget_vm_class_name_caches(other_vm);
    }

