    // JIT round 18 wave 11, lane mhresid (MHLOADER18-4): a member class whose
    // outer class cannot be resolved. The ICCE checks' reader keeps `None`;
    // `getDeclaringClass0`'s propagating lookup answers the resolution error,
    // as HotSpot's `compute_enclosing_class` (`klass_at`, `CHECK_NULL`) does.
    #[test]
    fn declaring_class_checked_answers_the_outer_resolution_error() {
        let mut ctx = mock_ctx();
        let inner = ctx
            .ensure_class_initialized("com/example/Gone$Inner")
            .unwrap();
        ctx.set_inner_classes(
            inner,
            vec![(
                "com/example/Gone$Inner".to_string(),
                "com/example/Gone".to_string(),
                "Inner".to_string(),
                0x0009,
            )],
        );
        ctx.fail_class_init("com/example/Gone");
        assert!(matches!(
            declaring_class_id_checked(&mut ctx, inner, false),
            Ok(None)
        ));
        assert_eq!(declaring_class_id_of(&mut ctx, inner), None);
        if outer_resolution_errors_apply(&ctx, inner) {
            assert!(declaring_class_id_checked(&mut ctx, inner, true).is_err());
        }
        // A JDK class keeps the old answer.
        let jdk = ctx
            .ensure_class_initialized("java/lang/Gone$Inner")
            .unwrap();
        assert!(!outer_resolution_errors_apply(&ctx, jdk));
    }

