    // -----------------------------------------------------------------------
    // Phase C hardening вЂ” wrapper matching, widening, strict coercion
    // -----------------------------------------------------------------------

    #[test]
    fn wrapper_matches_primitive_exact() {
        assert!(wrapper_matches_primitive("java/lang/Integer", "I"));
        assert!(wrapper_matches_primitive("java/lang/Long", "J"));
        assert!(wrapper_matches_primitive("java/lang/Float", "F"));
        assert!(wrapper_matches_primitive("java/lang/Double", "D"));
        assert!(wrapper_matches_primitive("java/lang/Boolean", "Z"));
        assert!(wrapper_matches_primitive("java/lang/Byte", "B"));
        assert!(wrapper_matches_primitive("java/lang/Short", "S"));
        assert!(wrapper_matches_primitive("java/lang/Character", "C"));
    }

    #[test]
    fn wrapper_matches_primitive_mismatch() {
        assert!(!wrapper_matches_primitive("java/lang/Integer", "J"));
        assert!(!wrapper_matches_primitive("java/lang/String", "I"));
        assert!(!wrapper_matches_primitive("java/lang/Long", "I"));
    }

    #[test]
    fn widening_allowed_spec_table() {
        // JLS В§5.1.2 widening conversions
        assert!(widening_allowed("B", "S"));
        assert!(widening_allowed("B", "I"));
        assert!(widening_allowed("B", "J"));
        assert!(widening_allowed("B", "F"));
        assert!(widening_allowed("B", "D"));
        assert!(widening_allowed("S", "I"));
        assert!(widening_allowed("S", "J"));
        assert!(widening_allowed("C", "I"));
        assert!(widening_allowed("C", "D"));
        assert!(widening_allowed("I", "J"));
        assert!(widening_allowed("I", "D"));
        assert!(widening_allowed("J", "F"));
        assert!(widening_allowed("F", "D"));
        // Identity is trivially allowed.
        assert!(widening_allowed("I", "I"));
    }

    #[test]
    fn widening_disallowed_narrowing() {
        // Narrowing conversions require an explicit cast; they are NOT
        // implicit widenings.
        assert!(!widening_allowed("J", "I"));
        assert!(!widening_allowed("D", "F"));
        assert!(!widening_allowed("I", "B"));
        assert!(!widening_allowed("I", "S"));
        assert!(!widening_allowed("I", "C"));
        // boolean does not widen to anything else.
        assert!(!widening_allowed("Z", "I"));
        assert!(!widening_allowed("I", "Z"));
        // short does not widen to char per JLS В§5.1.2 (explicit cast only).
        assert!(!widening_allowed("S", "C"));
        assert!(!widening_allowed("C", "S"));
    }

    #[test]
    fn widen_primitive_value_int_to_long() {
        let v = widen_primitive_value(Value::Int(42), "I", "J").unwrap();
        assert_eq!(v, Value::Long(42));
    }

    #[test]
    fn widen_primitive_value_int_to_double() {
        let v = widen_primitive_value(Value::Int(7), "I", "D").unwrap();
        match v {
            Value::Double(d) => assert!((d - 7.0).abs() < f64::EPSILON),
            other => panic!("expected Double, got {other:?}"),
        }
    }

    #[test]
    fn widen_primitive_value_disallowed_returns_none() {
        assert!(widen_primitive_value(Value::Long(1), "J", "I").is_none());
        assert!(widen_primitive_value(Value::Double(1.0), "D", "F").is_none());
    }

    #[test]
    fn wrapper_to_prim_desc_known_and_unknown() {
        assert_eq!(wrapper_to_prim_desc("java/lang/Integer"), Some("I"));
        assert_eq!(wrapper_to_prim_desc("java/lang/Boolean"), Some("Z"));
        assert_eq!(wrapper_to_prim_desc("java/lang/String"), None);
    }

    #[test]
    fn coerce_arg_strict_primitive_value_stays() {
        let mut ctx = mock_ctx();
        let v = coerce_arg_strict(&ctx, Value::Int(7), "I", "test", None).unwrap();
        assert_eq!(v, Value::Int(7));
        // int в†’ long widening is allowed implicitly.
        let v = coerce_arg_strict(&ctx, Value::Int(7), "J", "test", None).unwrap();
        assert_eq!(v, Value::Long(7));
        // long в†’ int is narrowing and must fail.
        let r = coerce_arg_strict(&ctx, Value::Long(7), "I", "test", None);
        assert!(r.is_err(), "narrowing long в†’ int should be rejected");
        drop(ctx);
    }

    #[test]
    fn coerce_arg_strict_null_to_primitive_errors() {
        let ctx = mock_ctx();
        let r = coerce_arg_strict(&ctx, Value::Object(None), "I", "test", None);
        assert!(r.is_err(), "null cannot be coerced to primitive");
    }

    /// A reflective write of the OTHER loader's copy of the field's own type is
    /// a loader split, not an `argument type mismatch`.
    ///
    /// # The run this comes from
    ///
    /// spring-framework's `TestContextAotGeneratorIntegrationTests`, 2026-08-10.
    /// log4j's plugin builder ran in the APPLICATION world — receiver,
    /// declaring class and field type all `ClassLoaderId::Application`,
    /// confirmed by `CRATONVM_DBG=coerce` — and was handed a `Level` from a
    /// `@CompileWithForkedClassLoader` world, because `TypeConverterRegistry`,
    /// `TypeConverters` and `PluginAttributeVisitor` exist ONLY in the forked
    /// worlds. Every `<Logger>` element of `log4j2-test.xml` was dropped with
    /// `Could not create plugin of type … LoggerConfig: argument type
    /// mismatch`, 28 times per run. HotSpot keeps that library in one world and
    /// never produces the mix, so the refusal had no HotSpot behaviour behind
    /// it — only our own loader modelling.
    ///
    /// # Both arms, because the lenient one alone is a degenerate `Ok`
    ///
    /// The negative is the control: an unrelated class must still be refused.
    /// Without it this test passes against a coercion that accepts everything,
    /// which is precisely the mistake to avoid on a check whose whole job is to
    /// reject. `is_subclass` is asserted `false` first so the acceptance cannot
    /// be legitimate subtyping in disguise.
    #[test]
    fn a_same_named_copy_from_another_loader_is_not_an_argument_type_mismatch() {
        const LEVEL: &str = "org/apache/logging/log4j/Level";
        let mut ctx = mock_ctx();

        // The copy by-name resolution finds — the field's declared type.
        let expected = ctx.ensure_class_initialized(LEVEL).expect("expected copy");
        // The other loader's copy, which is what the value is an instance of.
        let other_copy = ctx.declare_second_copy(LEVEL);
        assert_ne!(expected, other_copy, "the two copies must be distinct ids");
        assert!(
            !ctx.is_subclass(other_copy, expected),
            "identity must refuse the two copies — otherwise the arm under test \
             never runs and this measures nothing",
        );

        let value = ctx.alloc_object(other_copy, 0);
        assert!(
            coerce_arg_strict(
                &ctx,
                Value::Object(Some(value)),
                "Lorg/apache/logging/log4j/Level;",
                "Field.set",
                None,
            )
            .is_ok(),
            "the other loader's copy of the field's own type must be accepted — \
             refusing it is the `argument type mismatch` that silently dropped \
             every <Logger> element of log4j's configuration",
        );

        // THE CONTROL. A genuinely unrelated class carries the expected name
        // nowhere in its chain and must still be refused.
        let unrelated = ctx
            .ensure_class_initialized("cratonvm/test/NotALevel")
            .expect("unrelated class");
        let wrong = ctx.alloc_object(unrelated, 0);
        assert!(
            coerce_arg_strict(
                &ctx,
                Value::Object(Some(wrong)),
                "Lorg/apache/logging/log4j/Level;",
                "Field.set",
                None,
            )
            .is_err(),
            "an unrelated class must still be an argument type mismatch — if \
             this starts passing, reflective coercion has stopped checking",
        );
    }

    #[test]
    fn coerce_arg_strict_reference_passes_through() {
        let mut ctx = mock_ctx();
        let obj = ctx.alloc_object(ClassId::new(0), 0);
        let v = coerce_arg_strict(
            &ctx,
            Value::Object(Some(obj)),
            "Ljava/lang/Object;",
            "test",
            None,
        )
        .unwrap();
        assert_eq!(v, Value::Object(Some(obj)));
        // null is legal for a reference type.
        let v = coerce_arg_strict(
            &ctx,
            Value::Object(None),
            "Ljava/lang/String;",
            "test",
            None,
        )
        .unwrap();
        assert_eq!(v, Value::Object(None));
    }

    /// Interpreter round i1 wave 47, lane L3: an array formal takes an array
    /// (the heap's answer, not a class-name prefix: a reference array's
    /// header names its component) and refuses a plain object.
    #[test]
    fn coerce_arg_strict_array_formal_takes_an_array_and_refuses_an_object() {
        let mut ctx = mock_ctx();
        let arr = ctx.new_array(cratonvm_types::ArrayElementType::Int, 1);
        let v = coerce_arg_strict(&ctx, Value::Object(Some(arr)), "[I", "test", None)
            .expect("an array passes an array formal");
        assert_eq!(v, Value::Object(Some(arr)));
        let obj = ctx.alloc_object(ClassId::new(0), 0);
        if ctx.class_name_of_id(ctx.class_id_of_object(obj)).is_some() {
            assert!(coerce_arg_strict(&ctx, Value::Object(Some(obj)), "[I", "test", None).is_err());
        }
    }

    /// t1 lane V2 (review of t1 lane H's array check): every array is
    /// assignable to `Object`, `Cloneable` and `Serializable` (JLS 10.8), and
    /// to no other class or interface formal. The three are answered before
    /// the hierarchy walk, which would judge the array's COMPONENT class id
    /// (the header's), so a `String[]` for `Cloneable` was refused.
    #[test]
    fn t1v2_an_array_is_assignable_to_object_cloneable_and_serializable_only() {
        let mut ctx = mock_ctx();
        // The formals resolve, and to plain (non-interface) classes in this
        // mock: the walk, if reached, refuses the array (its class id is not
        // a subclass of any of them).
        for name in [
            "java/lang/Cloneable",
            "java/io/Serializable",
            "java/lang/CharSequence",
        ] {
            ctx.ensure_class_initialized(name).expect("formal class");
        }
        let component = ctx
            .ensure_class_initialized("java/lang/String")
            .expect("component");
        let refs = ctx.new_ref_array(component, 2);
        let ints = ctx.new_array(cratonvm_types::ArrayElementType::Int, 2);
        for arr in [refs, ints] {
            for formal in [
                "Ljava/lang/Object;",
                "Ljava/lang/Cloneable;",
                "Ljava/io/Serializable;",
            ] {
                let v = coerce_arg_strict(&ctx, Value::Object(Some(arr)), formal, "test", None)
                    .unwrap_or_else(|_| panic!("an array is assignable to {formal}"));
                assert_eq!(v, Value::Object(Some(arr)));
            }
            assert!(
                coerce_arg_strict(
                    &ctx,
                    Value::Object(Some(arr)),
                    "Ljava/lang/CharSequence;",
                    "test",
                    None
                )
                .is_err(),
                "an array is not a CharSequence"
            );
        }
    }

