    /// A `protected` field is reachable from a subclass in a foreign package
    /// (JLS 6.6.2).
    #[test]
    fn field_access_allows_protected_field_from_a_foreign_package_subclass() {
        let mut ctx = mock_ctx();
        let declaring = ctx
            .ensure_class_initialized("cratonvm/test/ProtOwner")
            .expect("declaring class");
        let caller = ctx
            .ensure_class_initialized("cratonvm/other/ProtChild")
            .expect("caller class");
        ctx.set_superclass(caller, declaring);
        ctx.set_frame_class_ids(vec![caller]);

        assert!(check_field_access(
            &mut ctx,
            0x0004, // protected
            false,
            declaring,
            None,
            "Field.get(protValue)"
        )
        .is_ok());
    }

    // -----------------------------------------------------------------------
    // JLS 6.6.2.1 - the RECEIVER refinement of the protected rule.
    //
    // Every row below is measured on Temurin 25.0.3 with
    // `ByteArrayOutputStream.buf` (protected, java.io exported-not-opened) read
    // from a classpath subclass, no setAccessible and no flags; the shape is
    // reproduced here on synthetic class ids so the whole matrix is testable
    // without a JDK. `object` is wired as the root of every chain because
    // `superclass_of` answering None is what the fail-open arm keys on, and a
    // test that never reaches a real root would pass for the wrong reason.
    // -----------------------------------------------------------------------

    /// Build ProtOwner <- ProtChild (the caller) plus a sibling and a
    /// grandchild, all rooted at a real `java/lang/Object`.
    fn protected_receiver_fixture(
        ctx: &mut crate::test_utils::MockNativeContext,
    ) -> (ClassId, ClassId, ClassId, ClassId) {
        let object = ctx
            .ensure_class_initialized("java/lang/Object")
            .expect("Object");
        let declaring = ctx
            .ensure_class_initialized("cratonvm/test/ProtOwner")
            .expect("declaring class");
        let caller = ctx
            .ensure_class_initialized("cratonvm/other/ProtChild")
            .expect("caller class");
        let grandchild = ctx
            .ensure_class_initialized("cratonvm/other/ProtGrandChild")
            .expect("grandchild class");
        let sibling = ctx
            .ensure_class_initialized("cratonvm/other/ProtSibling")
            .expect("sibling class");
        ctx.set_superclass(declaring, object);
        ctx.set_superclass(caller, declaring);
        ctx.set_superclass(grandchild, caller);
        ctx.set_superclass(sibling, declaring);
        (declaring, caller, grandchild, sibling)
    }

    fn protected_read_with_receiver(
        ctx: &mut crate::test_utils::MockNativeContext,
        declaring: ClassId,
        receiver: Option<ClassId>,
    ) -> bool {
        check_field_access(
            ctx,
            0x0004, // protected
            false,
            declaring,
            receiver,
            "Field.get(protValue)",
        )
        .is_ok()
    }

    /// ALLOW: the receiver is the caller's own class. HotSpot row H1.
    #[test]
    fn protected_receiver_allows_the_callers_own_class() {
        let mut ctx = mock_ctx();
        let (declaring, caller, _grandchild, _sibling) = protected_receiver_fixture(&mut ctx);
        ctx.set_frame_class_ids(vec![caller]);
        assert!(protected_read_with_receiver(
            &mut ctx,
            declaring,
            Some(caller)
        ));
    }

    /// ALLOW: the receiver is a SUBCLASS of the caller. HotSpot row H1b.
    #[test]
    fn protected_receiver_allows_a_subclass_of_the_caller() {
        let mut ctx = mock_ctx();
        let (declaring, caller, grandchild, _sibling) = protected_receiver_fixture(&mut ctx);
        ctx.set_frame_class_ids(vec![caller]);
        assert!(protected_read_with_receiver(
            &mut ctx,
            declaring,
            Some(grandchild)
        ));
    }

    /// DENY: the receiver is the DECLARING class itself. HotSpot row H2 - the
    /// row that was accidentally right before the module gate was corrected,
    /// and became a live divergence when it was.
    #[test]
    fn protected_receiver_rejects_the_declaring_class() {
        let mut ctx = mock_ctx();
        let (declaring, caller, _grandchild, _sibling) = protected_receiver_fixture(&mut ctx);
        ctx.set_frame_class_ids(vec![caller]);
        assert!(!protected_read_with_receiver(
            &mut ctx,
            declaring,
            Some(declaring)
        ));
    }

    /// DENY: the receiver is a SIBLING subclass - a subclass of the DECLARING
    /// class that is not under the CALLER. This is the row that reads as
    /// surprising: being a subclass of the declaring class is not the test.
    /// HotSpot row H2b.
    #[test]
    fn protected_receiver_rejects_a_sibling_subclass() {
        let mut ctx = mock_ctx();
        let (declaring, caller, _grandchild, sibling) = protected_receiver_fixture(&mut ctx);
        ctx.set_frame_class_ids(vec![caller]);
        assert!(!protected_read_with_receiver(
            &mut ctx,
            declaring,
            Some(sibling)
        ));
    }

    /// A `protected` STATIC field is exempt: `Field.checkAccess` passes a null
    /// `targetClass` for it, and HotSpot reads it OK through every receiver
    /// including a sibling and an unrelated class. `None` is how that reaches
    /// here, and it must not deny.
    #[test]
    fn protected_receiver_refinement_does_not_apply_to_a_static_field() {
        let mut ctx = mock_ctx();
        let (declaring, caller, _grandchild, _sibling) = protected_receiver_fixture(&mut ctx);
        ctx.set_frame_class_ids(vec![caller]);
        assert!(check_field_access(
            &mut ctx,
            0x0004 | 0x0008, // protected static
            false,
            declaring,
            None, // `reflective_target_class_id` maps every static receiver here
            "Field.get(protStaticValue)"
        )
        .is_ok());
    }

    /// FAIL OPEN: a receiver whose superclass chain cannot be walked to
    /// `java/lang/Object` is an unreadable input, not a denial. A synthetic-JDK
    /// stand-in is exactly this shape - fabricated, with supertypes modelled
    /// only where a stub table declares them - and a rule about real class
    /// hierarchies must not catch it.
    #[test]
    fn protected_receiver_fails_open_on_an_unrooted_receiver_chain() {
        let mut ctx = mock_ctx();
        let (declaring, caller, _grandchild, _sibling) = protected_receiver_fixture(&mut ctx);
        // Deliberately NOT given a superclass: `superclass_of` answers None at
        // the very first step and the class is not `java/lang/Object`.
        let standin = ctx
            .ensure_class_initialized("cratonvm/synthetic/FabricatedStandIn")
            .expect("stand-in class");
        ctx.set_frame_class_ids(vec![caller]);
        assert!(protected_read_with_receiver(
            &mut ctx,
            declaring,
            Some(standin)
        ));
    }

    /// The refinement is confined to `protected`. A package-private field read
    /// by a same-runtime-package caller stays allowed through a receiver that
    /// is not under the caller at all - HotSpot rows N1/N2 (public) and Q3
    /// (package-private, same package) all answer OK.
    #[test]
    fn protected_receiver_refinement_does_not_apply_to_a_package_private_field() {
        let mut ctx = mock_ctx();
        let object = ctx
            .ensure_class_initialized("java/lang/Object")
            .expect("Object");
        let declaring = ctx
            .ensure_class_initialized("cratonvm/test/PkgOwner")
            .expect("declaring class");
        let caller = ctx
            .ensure_class_initialized("cratonvm/test/PkgPeer")
            .expect("caller class");
        let unrelated = ctx
            .ensure_class_initialized("cratonvm/test/Unrelated")
            .expect("unrelated class");
        ctx.set_superclass(declaring, object);
        ctx.set_superclass(caller, object);
        ctx.set_superclass(unrelated, object);
        ctx.set_frame_class_ids(vec![caller]);
        assert!(check_field_access(
            &mut ctx,
            0x0000, // package-private
            false,
            declaring,
            Some(unrelated),
            "Field.get(pkgValue)"
        )
        .is_ok());
    }

    /// A null receiver on an INSTANCE field is a NullPointerException and it
    /// outranks every access refusal - HotSpot evaluates `obj.getClass()` while
    /// building `checkAccess`'s argument list. `String.hash.get(null)` from a
    /// foreign caller answers NullPointerException on Temurin 25.0.3 even
    /// though the field is denied on three separate grounds.
    #[test]
    fn null_receiver_on_an_instance_field_outranks_the_access_refusal() {
        use cratonvm_types::error::{MethodCallFailed, RuntimeError, VmError};
        let err = null_receiver_on_instance_field(false, None, None)
            .expect_err("a null receiver on an instance field must fail");
        // G69-1: the message is NULL, as HotSpot's is on four of the five entry
        // points. It used to read "Field.get: null receiver for instance
        // field", which no JDK ever emits.
        assert!(
            matches!(
                &err,
                MethodCallFailed::InternalError(VmError::Runtime(
                    RuntimeError::NullPointerException { message: None }
                ))
            ),
            "expected a NullPointerException with a null message, got: {err:?}"
        );
        // The generic `Field.set` is the exception, and carries HotSpot's own
        // helpful NPE text.
        //
        // Compared against `ENSURE_OBJ_NPE` itself, not searched for inside
        // `format!("{:?}")`. That is what this assertion did until now, and it
        // could not pass: `Debug` for a `String` ESCAPES its quotes, so the
        // rendering contains `because \"o\" is null` while the needle was the
        // unescaped `because "o" is null`. The production message has been
        // correct since the assertion was written (2026-08-18) — it is the
        // literal `ENSURE_OBJ_NPE` this call passes in — and only the test was
        // wrong. Matching the constant is also strictly stronger than a
        // substring: it pins the whole text, including the `Object.getClass()`
        // half that names WHICH dereference HotSpot reports.
        let with_msg = null_receiver_on_instance_field(false, None, Some(ENSURE_OBJ_NPE))
            .expect_err("a null receiver on an instance field must fail");
        match &with_msg {
            MethodCallFailed::InternalError(VmError::Runtime(
                RuntimeError::NullPointerException { message: Some(m) },
            )) => assert_eq!(m.as_str(), ENSURE_OBJ_NPE),
            other => panic!("expected HotSpot's helpful NPE, got: {other:?}"),
        }
        // ...and a STATIC field has no receiver to be null.
        assert!(null_receiver_on_instance_field(true, None, None).is_ok());
    }

    /// Interpreter round i2 wave 54, lane L3: the JDK accessor chains of a
    /// `Field` raise, as `L3W54FieldOverrideAccessorFrames` measured them on
    /// JDK 25.0.3 (innermost last here: the chain is OUTERMOST first).
    #[test]
    fn field_raise_chains_follow_the_jdk_accessor() {
        let names = |method, is_set, descriptor: &str, accessible, raise| -> Vec<String> {
            field_raise_chain(method, is_set, descriptor, accessible, raise)
                .expect("a chain")
                .hops
                .iter()
                .map(|hop| {
                    format!(
                        "{}.{}",
                        hop.class.rsplit('/').next().unwrap_or(""),
                        hop.name
                    )
                })
                .collect()
        };
        let get_long = field_typed_getter("long").unwrap();
        let set_int = field_typed_setter("int").unwrap();
        // acc-get-int
        assert_eq!(
            names(FIELD_GET, false, "I", true, FieldRaise::NullReceiver),
            [
                "Field.get",
                "MethodHandleIntegerFieldAccessorImpl.get",
                "MethodHandleIntegerFieldAccessorImpl.getInt",
                "DirectMethodHandle.checkBase",
                "Objects.requireNonNull"
            ]
        );
        // acc-getLong-int
        assert_eq!(
            names(get_long, false, "I", true, FieldRaise::NullReceiver)[1..3],
            [
                "MethodHandleIntegerFieldAccessorImpl.getLong",
                "MethodHandleIntegerFieldAccessorImpl.getInt"
            ]
        );
        // acc-get-object: the Object accessor's `get` is its primary one.
        assert_eq!(
            names(
                FIELD_GET,
                false,
                "Ljava/lang/Object;",
                true,
                FieldRaise::NullReceiver
            )[1..3],
            [
                "MethodHandleObjectFieldAccessorImpl.get",
                "DirectMethodHandle.checkBase"
            ]
        );
        // acc-setInt-long: the long accessor's `setInt` widens to `setLong`.
        assert_eq!(
            names(set_int, true, "J", true, FieldRaise::NullReceiver)[1..3],
            [
                "MethodHandleLongFieldAccessorImpl.setInt",
                "MethodHandleLongFieldAccessorImpl.setLong"
            ]
        );
        // acc-set-int: `ensureObj`'s `o.getClass()`.
        assert_eq!(
            names(FIELD_SET, true, "I", true, FieldRaise::NullReceiver),
            [
                "Field.set",
                "MethodHandleIntegerFieldAccessorImpl.set",
                "MethodHandleFieldAccessorImpl.ensureObj"
            ]
        );
        // wrong-set: two `throwSetIllegalArgumentException` frames.
        assert_eq!(
            names(FIELD_SET, true, "I", false, FieldRaise::WrongReceiver)[2..],
            [
                "MethodHandleFieldAccessorImpl.ensureObj",
                "FieldAccessorImpl.throwSetIllegalArgumentException",
                "FieldAccessorImpl.throwSetIllegalArgumentException"
            ]
        );
        // wrong-getInt: `newGetIllegalArgumentException` under `getInt`.
        let get_int = field_typed_getter("int").unwrap();
        assert_eq!(
            names(get_int, false, "I", false, FieldRaise::WrongReceiver),
            [
                "Field.getInt",
                "MethodHandleIntegerFieldAccessorImpl.getInt",
                "MethodHandleFieldAccessorImpl.newGetIllegalArgumentException"
            ]
        );
        // `Field.<accessor>`: the first call of the accessor without the
        // override, the last with it.
        let first_site = |accessible| {
            field_raise_chain(get_int, false, "I", accessible, FieldRaise::WrongReceiver)
                .unwrap()
                .hops[0]
                .site
        };
        assert!(matches!(
            first_site(false),
            cratonvm_native_api::ServedRaiseHopSite::FirstCall { name: "getInt", .. }
        ));
        assert!(matches!(
            first_site(true),
            cratonvm_native_api::ServedRaiseHopSite::LastCall { name: "getInt", .. }
        ));
        assert!(field_raise_chain(FIELD_GET, false, "", true, FieldRaise::NullReceiver).is_none());
    }

    /// Interpreter round i3 wave 74, lane L3: `Method.invoke`'s and
    /// `Constructor.newInstance`'s access refusals list
    /// `AccessibleObject.checkAccess` -> `Reflection.newIllegalAccessException`
    /// under the served method (through `newInstanceWithCaller` for a
    /// constructor), the last building the throwable.
    #[test]
    fn executable_access_refusal_chain_ends_in_new_illegal_access_exception() {
        use cratonvm_native_api::ServedRaiseHopSite;
        let render = |constructor: bool| -> Vec<String> {
            let c = executable_access_refusal_chain(constructor);
            assert_eq!(c.throwable_class, "java/lang/IllegalAccessException");
            assert_eq!(c.hops.last().unwrap().site, ServedRaiseHopSite::Raise);
            c.hops
                .iter()
                .map(|hop| format!("{}.{}{}", hop.class, hop.name, hop.descriptor))
                .collect()
        };
        let tail = [
            "java/lang/reflect/AccessibleObject.checkAccess(Ljava/lang/Class;Ljava/lang/Class;Ljava/lang/Class;I)V",
            "jdk/internal/reflect/Reflection.newIllegalAccessException(Ljava/lang/Class;Ljava/lang/Class;Ljava/lang/Class;I)Ljava/lang/IllegalAccessException;",
        ];
        let mut method = vec![
            "java/lang/reflect/Method.invoke(Ljava/lang/Object;[Ljava/lang/Object;)Ljava/lang/Object;",
        ];
        method.extend(tail);
        assert_eq!(render(false), method);
        let mut ctor = vec![
            "java/lang/reflect/Constructor.newInstance([Ljava/lang/Object;)Ljava/lang/Object;",
            "java/lang/reflect/Constructor.newInstanceWithCaller([Ljava/lang/Object;ZLjava/lang/Class;)Ljava/lang/Object;",
        ];
        ctor.extend(tail);
        assert_eq!(render(true), ctor);
        // Each hop stands at its LAST call of the next one.
        let c = executable_access_refusal_chain(true);
        assert!(matches!(
            c.hops[0].site,
            ServedRaiseHopSite::LastCall {
                name: "newInstanceWithCaller",
                ..
            }
        ));
        assert!(matches!(
            c.hops[1].site,
            ServedRaiseHopSite::LastCall {
                name: "checkAccess",
                ..
            }
        ));
    }

    /// Interpreter round i3 wave 74, lane L3 (`CRATONVM_FIELD_DOOR_IDENT_MEMO`):
    /// a memo row answers only the member it was built for, and an identity
    /// whose texts are shared prints every refusal grammar byte for byte as
    /// one whose texts were built for the call.
    #[test]
    fn field_ident_memo_rows_answer_their_own_member_and_print_the_same_text() {
        let memo = FieldIdentMemo::new();
        let decl: Arc<str> = Arc::from("P$H");
        let key = (17u32, 3usize, false);
        assert!(memo.lookup(key, &decl, "I", ACC_PUBLIC).is_none());
        memo.remember(
            key,
            FieldIdentRow {
                decl: Arc::clone(&decl),
                descriptor: Box::from("I"),
                modifiers: ACC_PUBLIC,
                qualified: Arc::from("P$H.f"),
                ty: Arc::from("int"),
            },
        );
        let (q, t) = memo
            .lookup(key, &decl, "I", ACC_PUBLIC)
            .expect("remembered");
        assert_eq!((&*q, &*t), ("P$H.f", "int"));
        // An equal name in another `Arc` still matches; anything else does not.
        assert!(memo
            .lookup(key, &Arc::from("P$H"), "I", ACC_PUBLIC)
            .is_some());
        assert!(memo
            .lookup(key, &Arc::from("Q$H"), "I", ACC_PUBLIC)
            .is_none());
        assert!(memo.lookup(key, &decl, "J", ACC_PUBLIC).is_none());
        assert!(memo
            .lookup(key, &decl, "I", ACC_PUBLIC | ACC_FINAL)
            .is_none());
        assert!(memo.lookup((17, 3, true), &decl, "I", ACC_PUBLIC).is_none());

        let modifiers = ACC_PUBLIC | ACC_STATIC | ACC_FINAL;
        let owned = FieldIdent::for_test("P$H.f", "int", modifiers);
        let shared = FieldIdent {
            qualified: IdentText::Shared(Arc::from("P$H.f")),
            ty: IdentText::Shared(Arc::from("int")),
            is_static: owned.is_static,
            is_final: owned.is_final,
            trusted_final: owned.trusted_final,
        };
        for id in [&owned, &shared] {
            assert_eq!(
                id.set_to("(int)9"),
                "Can not set static final int field P$H.f to (int)9"
            );
            assert_eq!(
                id.get_conversion("long"),
                "Attempt to get int field \"P$H.f\" with illegal data type conversion to long"
            );
            assert_eq!(id.ty(), "int");
            assert_eq!(id.qualified.to_string(), "P$H.f");
        }
    }

    /// Interpreter round i3 wave 74, lane L3 (`CRATONVM_REFLECT_INVOKE_PLAN`):
    /// a plan is interned once per (class, name, descriptor), answers the
    /// facts the by-name path parses, and is never shared with a different
    /// member that reuses the key (a reused class id).
    #[test]
    fn method_plans_intern_once_per_member_and_answer_the_parsed_facts() {
        let plans = MethodPlans::new();
        let cid = ClassId::new(41);
        let name: Arc<str> = Arc::from("p/Target");
        let one = plans.intern(cid, Arc::clone(&name), "one", "(I)I", 0x0009);
        assert!(one >= 1);
        assert_eq!(
            plans.intern(cid, Arc::clone(&name), "one", "(I)I", 0x0009),
            one
        );
        let two = plans.intern(cid, Arc::clone(&name), "one", "(J)I", 0x0009);
        assert_ne!(two, one);
        let p = plans.get(one).expect("interned");
        assert_eq!(p.class_id, cid);
        assert_eq!(&*p.class_name, "p/Target");
        assert_eq!(&*p.name, "one");
        assert_eq!(&*p.descriptor, "(I)I");
        assert_eq!(p.param_descs, vec!["I".to_string()]);
        assert_eq!(p.ret_desc, "I");
        assert_eq!(p.modifiers, 0x0009);
        assert!(!p.declaring_is_object);
        let (params, ret) = parse_descriptor_param_and_return("(Ljava/lang/String;[J)V");
        let q = plans
            .get(plans.intern(cid, Arc::clone(&name), "two", "(Ljava/lang/String;[J)V", 1))
            .unwrap();
        assert_eq!((q.param_descs.clone(), q.ret_desc.clone()), (params, ret));
        // The same key under another class name (or modifiers): a new plan.
        let other = plans.intern(cid, Arc::from("q/Other"), "one", "(I)I", 0x0009);
        assert_ne!(other, one);
        assert_eq!(&*plans.get(other).unwrap().class_name, "q/Other");
        assert_ne!(
            plans.intern(cid, Arc::from("q/Other"), "one", "(I)I", 0x0001),
            other
        );
        // `java/lang/Object`'s methods take every receiver.
        let obj = plans.intern(
            ClassId::new(1),
            Arc::from("java/lang/Object"),
            "hashCode",
            "()I",
            1,
        );
        assert!(plans.get(obj).unwrap().declaring_is_object);
        // No plan: `slot` 0 (the switch off), a negative or unknown id.
        assert!(plans.get(0).is_none());
        assert!(plans.get(-3).is_none());
        assert!(plans.get(10_000).is_none());
        // Wave 75 (lane L3): a new plan is not settled.
        let fresh = plans.get(one).unwrap();
        assert_eq!(fresh.settled.load(std::sync::atomic::Ordering::Relaxed), 0);
        // Wave 76 (lane L3): the accessors the boxing wrapper reads.
        assert_eq!(fresh.ret_desc(), "I");
        assert_eq!(fresh.descriptor(), "(I)I");
        // Wave 77 (lane L3): `intern` keeps no class flags.
        assert_eq!(fresh.class_flags, None);
    }

    /// Interpreter round i3 wave 77, lane L3 (`CRATONVM_REFLECT_INVOKE_PLAN_FACTS`):
    /// a plan interned with the declaring class's flags keeps them; the same
    /// member interned again answers the same plan.
    #[test]
    fn method_plans_keep_the_class_flags_they_were_interned_with() {
        let plans = MethodPlans::new();
        let cid = ClassId::new(43);
        let name: Arc<str> = Arc::from("p/Kept");
        let id = plans.intern_with_flags(cid, Arc::clone(&name), "f", "()V", 0x0001, Some(0x0021));
        assert!(id >= 1);
        assert_eq!(plans.get(id).unwrap().class_flags, Some(0x0021));
        assert_eq!(
            plans.intern_with_flags(cid, Arc::clone(&name), "f", "()V", 0x0001, Some(0x0021)),
            id
        );
        let other = plans.intern(cid, Arc::clone(&name), "g", "()V", 0x0001);
        assert_eq!(plans.get(other).unwrap().class_flags, None);
    }

    /// Interpreter round i3 wave 77, lane L3 (`CRATONVM_REFLECT_INVOKE_PLAN_FACTS`):
    /// the class half of `verifyMemberAccess` answers the same from a kept
    /// flags word as from the class-manager read of that word -- public,
    /// package-private and unreadable (`0`) classes alike.
    #[test]
    fn class_reachability_from_kept_flags_matches_the_read() {
        let mut ctx = mock_ctx();
        let declaring = ctx.declare_loaded_class("p/Declaring");
        for flags in [0u16, 0x0021, 0x0020, 0x0030] {
            ctx.set_class_access_flags(declaring, flags);
            let read =
                member_class_is_reachable_by_runtime_package(&mut ctx, declaring, Some(None));
            let kept = member_class_is_reachable_by_runtime_package_with_flags(
                &mut ctx,
                declaring,
                flags,
                Some(None),
            );
            assert_eq!(read, kept, "flags {flags:#06x}");
        }
    }

    /// Interpreter round i3 wave 76, lane L3 (`CRATONVM_REFLECT_DOOR_WORD_BATCH`):
    /// a plan remembers the `Method` object class's extra-slot base and
    /// answers what [`method_extra_base`] answers, for that class and for a
    /// different one (which replaces the remembered row).
    #[test]
    fn method_plan_remembers_the_method_object_extra_base() {
        let mut ctx = mock_ctx();
        let method_cid = ctx.declare_loaded_class("java/lang/reflect/Method");
        let other_cid = ctx.declare_loaded_class("p/NotAMethod");
        let plan = MethodPlan::new(
            ClassId::new(41),
            Arc::from("p/Target"),
            "one",
            "(I)I",
            0x0009,
            None,
        );
        let ctx_ref: &dyn NativeContext = &ctx;
        assert_eq!(
            plan.extra_base.load(std::sync::atomic::Ordering::Relaxed),
            0
        );
        let base = plan.method_extra_base_cached(ctx_ref, method_cid);
        assert_eq!(base, method_extra_base(ctx_ref, method_cid));
        assert_ne!(
            plan.extra_base.load(std::sync::atomic::Ordering::Relaxed),
            0
        );
        assert_eq!(plan.method_extra_base_cached(ctx_ref, method_cid), base);
        assert_eq!(
            plan.method_extra_base_cached(ctx_ref, other_cid),
            method_extra_base(ctx_ref, other_cid)
        );
        assert_eq!(plan.method_extra_base_cached(ctx_ref, method_cid), base);
    }

    /// Interpreter round i3 wave 76, lane L3 (`CRATONVM_REFLECT_DOOR_WORD_BATCH`):
    /// the accessible flag read from a batched `override` word is the full
    /// read's answer -- the word itself when non-zero, else the extra slot
    /// when the object carries the tail, else `false`.
    #[test]
    fn batched_method_accessible_read_matches_the_full_read() {
        let mut ctx = mock_ctx();
        let method_cid = ctx.declare_loaded_class("java/lang/reflect/Method");
        let plan = MethodPlan::new(
            ClassId::new(41),
            Arc::from("p/Target"),
            "one",
            "(I)I",
            0x0001,
            None,
        );
        let base = method_extra_base(&ctx, method_cid);
        let tailed = ctx.alloc_object(method_cid, base + METHOD_EXTRA_OFFSET_ACCESSIBLE + 1);
        let bare = ctx.alloc_object(method_cid, base);
        for (obj, extra) in [(tailed, Some(1)), (tailed, Some(0)), (bare, None)] {
            if let Some(v) = extra {
                ctx.set_field(obj, base + METHOD_EXTRA_OFFSET_ACCESSIBLE, Value::Int(v));
            }
            let ctx_ref: &dyn NativeContext = &ctx;
            let word = ctx_ref.get_field_by_name(obj, "override");
            assert_eq!(
                read_method_accessible_batched(ctx_ref, obj, word, &plan),
                read_method_accessible(ctx_ref, obj),
                "extra slot {extra:?}"
            );
            assert!(read_method_accessible_batched(
                ctx_ref,
                obj,
                Value::Int(1),
                &plan
            ));
        }
        let ctx_ref: &dyn NativeContext = &ctx;
        assert!(!read_method_accessible_batched(
            ctx_ref,
            tailed,
            Value::Int(0),
            &plan
        ));
        assert!(!read_method_accessible_batched(
            ctx_ref,
            bare,
            Value::Int(0),
            &plan
        ));
    }

    /// Interpreter round i3 wave 75, lane L3 (`CRATONVM_REFLECT_CTOR_PLAN_PER_VM`):
    /// the per-VM constructor plans intern once per (class, descriptor),
    /// keep the declaring class's flags, and never hand a reused class id's
    /// row to a constructor of a differently named class.
    #[test]
    fn ctor_plans_intern_once_per_constructor_and_keep_the_class_flags() {
        let mut ctx = mock_ctx();
        let cid = ctx.declare_loaded_class("p/Target");
        ctx.set_class_access_flags(cid, 0x0001 | 0x0400);
        let meta =
            |descriptor: &str, access_flags: u16, declaring_class_id: ClassId| MethodMetadata {
                name: "<init>".to_string(),
                descriptor: descriptor.to_string(),
                access_flags,
                declaring_class_id,
                exceptions: Vec::new(),
                signature: None,
            };
        let plans = CtorPlans::new();
        let ctx_ref: &dyn NativeContext = &ctx;
        let one = plans.intern(ctx_ref, &meta("(I)V", 0x0001, cid));
        assert!(one >= 1);
        assert_eq!(plans.intern(ctx_ref, &meta("(I)V", 0x0001, cid)), one);
        let two = plans.intern(ctx_ref, &meta("()V", 0x0002, cid));
        assert!(two >= 1 && two != one);
        let p = plans.get(one).expect("interned");
        assert_eq!(p.class_id, cid);
        assert_eq!(&*p.class_name, "p/Target");
        assert_eq!(&*p.descriptor, "(I)V");
        assert_eq!(*p.param_descs, vec!["I".to_string()]);
        assert_eq!(p.modifiers, 0x0001);
        assert_eq!(p.class_flags, Some(0x0001 | 0x0400));
        // Other modifiers under the same key: a new row, not the old one.
        let three = plans.intern(ctx_ref, &meta("(I)V", 0x0004, cid));
        assert!(three != one && three != two);
        assert_eq!(plans.get(three).unwrap().modifiers, 0x0004);
        // An unnamed class gets no plan; slot 0, a negative or unknown id
        // names none.
        assert_eq!(
            plans.intern(ctx_ref, &meta("()V", 1, ClassId::new(9_999))),
            0
        );
        assert!(plans.get(0).is_none());
        assert!(plans.get(-1).is_none());
        assert!(plans.get(10_000).is_none());
    }

    /// Interpreter round i3 wave 73, lane L3: an access refusal lists
    /// `Field.checkAccess` -> `AccessibleObject.checkAccess` ->
    /// `Reflection.newIllegalAccessException` under the `Field` method, the
    /// last building the throwable.
    #[test]
    fn field_access_refusal_chain_ends_in_new_illegal_access_exception() {
        use cratonvm_native_api::ServedRaiseHopSite;
        let get_int = field_typed_getter("int").unwrap();
        let c = field_access_refusal_chain(get_int);
        assert_eq!(c.throwable_class, "java/lang/IllegalAccessException");
        let names: Vec<String> = c
            .hops
            .iter()
            .map(|hop| format!("{}.{}{}", hop.class, hop.name, hop.descriptor))
            .collect();
        assert_eq!(
            names,
            [
                "java/lang/reflect/Field.getInt(Ljava/lang/Object;)I",
                "java/lang/reflect/Field.checkAccess(Ljava/lang/Class;Ljava/lang/Object;)V",
                "java/lang/reflect/AccessibleObject.checkAccess(Ljava/lang/Class;Ljava/lang/Class;Ljava/lang/Class;I)V",
                "jdk/internal/reflect/Reflection.newIllegalAccessException(Ljava/lang/Class;Ljava/lang/Class;Ljava/lang/Class;I)Ljava/lang/IllegalAccessException;",
            ]
        );
        assert_eq!(c.hops.last().unwrap().site, ServedRaiseHopSite::Raise);
        assert!(matches!(
            c.hops[0].site,
            ServedRaiseHopSite::LastCall {
                name: "checkAccess",
                ..
            }
        ));
    }

    /// Interpreter round i2 wave 57, lane L3: the value refusals' chains, as
    /// `L3W57FieldRefusalFrames` measured them on JDK 25.0.3.
    #[test]
    fn field_value_refusal_chains_follow_the_jdk_accessor() {
        use cratonvm_native_api::ServedRaiseHopSite;
        let chain = |method, is_set, descriptor: &str, raise| {
            field_raise_chain(method, is_set, descriptor, false, raise).expect("a chain")
        };
        let names = |c: &cratonvm_native_api::ServedRaiseChain| -> Vec<String> {
            c.hops
                .iter()
                .map(|hop| {
                    format!(
                        "{}.{}{}",
                        hop.class.rsplit('/').next().unwrap_or(""),
                        hop.name,
                        hop.descriptor
                    )
                })
                .collect()
        };
        // final-set
        let c = chain(FIELD_SET, true, "I", FieldRaise::FinalField);
        assert_eq!(c.throwable_class, "java/lang/IllegalAccessException");
        assert_eq!(
            names(&c)[1..],
            [
                "MethodHandleIntegerFieldAccessorImpl.set(Ljava/lang/Object;Ljava/lang/Object;)V",
                "FieldAccessorImpl.throwFinalFieldIllegalAccessException(Ljava/lang/Object;)V",
                "FieldAccessorImpl.throwFinalFieldIllegalAccessException(Ljava/lang/String;Ljava/lang/String;)V"
            ]
        );
        assert_eq!(c.hops.last().unwrap().site, ServedRaiseHopSite::Raise);
        // final-setByte: `setByte` widens to `setInt`, which refuses at `int`.
        let set_byte = field_typed_setter("byte").unwrap();
        assert_eq!(
            names(&chain(set_byte, true, "I", FieldRaise::FinalField))[1..4],
            [
                "MethodHandleIntegerFieldAccessorImpl.setByte(Ljava/lang/Object;B)V",
                "MethodHandleIntegerFieldAccessorImpl.setInt(Ljava/lang/Object;I)V",
                "FieldAccessorImpl.throwFinalFieldIllegalAccessException(I)V"
            ]
        );
        // final-setInt-long
        let set_int = field_typed_setter("int").unwrap();
        assert_eq!(
            names(&chain(set_int, true, "J", FieldRaise::FinalField))[3],
            "FieldAccessorImpl.throwFinalFieldIllegalAccessException(J)V"
        );
        // A typed setter never reaches a reference field's final refusal.
        assert!(field_raise_chain(
            set_int,
            true,
            "Ljava/lang/Object;",
            false,
            FieldRaise::FinalField
        )
        .is_none());
        // value-set / value-set-null: the last and the first of the two calls.
        let site = |null_value| {
            chain(
                FIELD_SET,
                true,
                "I",
                FieldRaise::SetValueType { null_value },
            )
            .hops[1]
                .site
        };
        assert!(matches!(site(false), ServedRaiseHopSite::LastCall { .. }));
        assert!(matches!(site(true), ServedRaiseHopSite::FirstCall { .. }));
        // value-setLong: `setLong` refuses at its own type.
        let set_long = field_typed_setter("long").unwrap();
        assert_eq!(
            names(&chain(
                set_long,
                true,
                "I",
                FieldRaise::SetValueType { null_value: false }
            ))[1..3],
            [
                "MethodHandleIntegerFieldAccessorImpl.setLong(Ljava/lang/Object;J)V",
                "FieldAccessorImpl.throwSetIllegalArgumentException(J)V"
            ]
        );
        // ro-setByte-wrong / rec-acc-setShort-null: a read-only field's
        // setter widens, then `ensureObj` refuses the receiver.
        let c = chain(set_byte, true, "I", FieldRaise::ReadOnlyWrongReceiver);
        assert_eq!(c.throwable_class, "java/lang/IllegalArgumentException");
        assert_eq!(
            names(&c)[1..],
            [
                "MethodHandleIntegerFieldAccessorImpl.setByte(Ljava/lang/Object;B)V",
                "MethodHandleIntegerFieldAccessorImpl.setInt(Ljava/lang/Object;I)V",
                "MethodHandleFieldAccessorImpl.ensureObj(Ljava/lang/Object;)V",
                "FieldAccessorImpl.throwSetIllegalArgumentException(Ljava/lang/Object;)V",
                "FieldAccessorImpl.throwSetIllegalArgumentException(Ljava/lang/String;Ljava/lang/String;)V"
            ]
        );
        let set_short = field_typed_setter("short").unwrap();
        let c = chain(set_short, true, "I", FieldRaise::ReadOnlyNullReceiver);
        assert_eq!(c.throwable_class, "java/lang/NullPointerException");
        assert_eq!(
            names(&c).last().unwrap(),
            "MethodHandleFieldAccessorImpl.ensureObj(Ljava/lang/Object;)V"
        );
        assert!(
            field_raise_chain(FIELD_SET, true, "I", true, FieldRaise::ReadOnlyNullReceiver)
                .is_none()
        );
        // get-getInt-object
        let get_int = field_typed_getter("int").unwrap();
        let c = chain(
            get_int,
            false,
            "Ljava/lang/Object;",
            FieldRaise::GetConversion,
        );
        assert_eq!(c.throwable_class, "java/lang/IllegalArgumentException");
        assert_eq!(
            names(&c)[1..],
            [
                "MethodHandleObjectFieldAccessorImpl.getInt(Ljava/lang/Object;)I",
                "FieldAccessorImpl.newGetIntIllegalArgumentException()Ljava/lang/IllegalArgumentException;",
                "FieldAccessorImpl.newGetIllegalArgumentException(Ljava/lang/String;)Ljava/lang/IllegalArgumentException;"
            ]
        );
    }

    /// Fail CLOSED when there is no resolvable Java caller frame: the
    /// entitlement step must never be reached, so the old blanket rule stands.
    #[test]
    fn field_access_rejects_private_field_when_no_caller_frame_resolves() {
        let mut ctx = mock_ctx();
        let declaring = ctx
            .ensure_class_initialized("cratonvm/test/PrivateFieldOwner")
            .expect("declaring class");
        ctx.set_frame_class_ids(Vec::new());

        assert!(check_field_access(
            &mut ctx,
            0x0002,
            false,
            declaring,
            None,
            "Field.get(privateValue)"
        )
        .is_err());
    }

    /// A private field of a class in the same package is still NOT reachable
    /// without a confirmed nest relationship - `private` is nest-scoped, never
    /// package-scoped (JEP 181). This pins the one arm that must not widen.
    #[test]
    fn field_access_rejects_private_field_from_a_same_package_non_nestmate() {
        let mut ctx = mock_ctx();
        let declaring = ctx
            .ensure_class_initialized("cratonvm/test/NestlessOwner")
            .expect("declaring class");
        let caller = ctx
            .ensure_class_initialized("cratonvm/test/NestlessPeer")
            .expect("caller class");
        ctx.set_frame_class_ids(vec![caller]);

        assert!(check_field_access(
            &mut ctx,
            0x0002, // private
            false,
            declaring,
            None,
            "Field.get(privateValue)"
        )
        .is_err());
    }

    /// L15's hidden-class residual, closed: a JEP 371 hidden class defined with
    /// `ClassOption::NESTMATE` IS a nestmate of the `Lookup`'s class, so a
    /// `private` member of it is reflectively reachable from that class.
    ///
    /// The host is deliberately given **no** `NestMembers` entry naming the
    /// hidden class, because no class file could spell that name. That is what
    /// makes this test non-vacuous: the confirmation round-trip in
    /// `confirmed_nest_host_name` CANNOT succeed here, so the only thing that
    /// can admit the access is the hidden-class arm. The paired test below is
    /// the same fixture with the hidden flag off, and it must stay red.
    #[test]
    fn field_access_allows_private_field_of_a_hidden_nestmate() {
        let mut ctx = mock_ctx();
        let caller = ctx
            .ensure_class_initialized("cratonvm/test/HiddenNestOwner")
            .expect("caller class");
        let declaring = ctx
            .ensure_class_initialized("cratonvm/test/HiddenNestOwner$$Lambda/0x1")
            .expect("hidden class");
        ctx.set_nest_host_override(declaring, "cratonvm/test/HiddenNestOwner");
        ctx.set_class_hidden(declaring);
        ctx.set_frame_class_ids(vec![caller]);

        assert!(check_field_access(
            &mut ctx,
            0x0002, // private
            false,
            declaring,
            None,
            "Field.get(privateValue)"
        )
        .is_ok());
    }

    /// The falsifier for the test above. Identical fixture, hidden flag NOT
    /// set: the `NestHost` claim is then just a claim, the host lists no such
    /// member, and the access must stay refused. Without this row the widening
    /// above could not be distinguished from "any `NestHost` claim is honoured",
    /// which is the spoof `confirmed_nest_host_name` exists to defeat.
    #[test]
    fn field_access_rejects_private_field_of_an_unconfirmed_non_hidden_claimant() {
        let mut ctx = mock_ctx();
        let caller = ctx
            .ensure_class_initialized("cratonvm/test/HiddenNestOwner")
            .expect("caller class");
        let declaring = ctx
            .ensure_class_initialized("cratonvm/test/SpoofingClaimant")
            .expect("declaring class");
        ctx.set_nest_host_override(declaring, "cratonvm/test/HiddenNestOwner");
        ctx.set_frame_class_ids(vec![caller]);

        assert!(check_field_access(
            &mut ctx,
            0x0002, // private
            false,
            declaring,
            None,
            "Field.get(privateValue)"
        )
        .is_err());
    }

    // -----------------------------------------------------------------------
    // Phase C вЂ” typed Field setters narrow via storage-size mask
    // -----------------------------------------------------------------------

    /// Helper: allocate a Field mirror object that references a storage
    /// field on an arbitrary target object. Used to drive the typed
    /// getters/setters without a full class-loader path.
    fn make_field_mirror(
        ctx: &mut crate::test_utils::MockNativeContext,
        name: &str,
        descriptor: &str,
        modifiers: i32,
        slot_index: i32,
    ) -> ObjectRef {
        // Allocate with room for the synthetic layout (slots 0..=6) plus
        // the CratonVM extra-metadata slots (descriptor, rj_slot,
        // accessible) that the production readers now consult.
        let obj = ctx.alloc_object(ClassId::new(0), FIELD_NUM_FIELDS + FIELD_EXTRA_SLOTS);
        // field 0: declaring class mirror (class_id = 1 arbitrary)
        let mirror = make_class_mirror(ctx, 1, "cratonvm/test/Fixture");
        ctx.set_field(obj, 0, Value::Object(Some(mirror)));
        let name_s = ctx.create_string(name);
        ctx.set_field(obj, 1, Value::Object(Some(name_s)));
        // field 2 unused in these tests
        ctx.set_field(obj, 3, Value::Int(modifiers));
        ctx.set_field(obj, 4, Value::Int(slot_index));
        let desc_s = ctx.create_string(descriptor);
        ctx.set_field(obj, 5, Value::Object(Some(desc_s)));
        ctx.set_field(obj, 6, Value::Int(1)); // accessible = true, bypass JPMS
                                              // Extra-slot metadata (matches create_field_object's layout).
        let base = FIELD_NUM_FIELDS;
        ctx.set_field(
            obj,
            base + FIELD_EXTRA_OFFSET_DESC,
            Value::Object(Some(desc_s)),
        );
        ctx.set_field(
            obj,
            base + FIELD_EXTRA_OFFSET_RJ_SLOT,
            Value::Int(slot_index),
        );
        ctx.set_field(obj, base + FIELD_EXTRA_OFFSET_ACCESSIBLE, Value::Int(1));
        obj
    }

    #[test]
    fn field_set_byte_masks_to_signed_8_bits() {
        let mut ctx = mock_ctx();
        let field = make_field_mirror(&mut ctx, "b", "B", ACC_PUBLIC, 0);
        let target = ctx.alloc_object(ClassId::new(1), 1);
        // Write 0x1_FF (511) вЂ” must narrow to signed byte value = -1.
        let r = native_field_set_byte(
            &mut ctx,
            &[
                Value::Object(Some(field)),
                Value::Object(Some(target)),
                Value::Int(0x1FF),
            ],
        );
        assert!(r.is_ok(), "setByte should succeed");
        assert_eq!(ctx.get_field(target, 0), Value::Int(-1));
    }

