    /// Interpreter round i5 wave 105, lane L3: a class of a named image
    /// module answers its module's resources only (JDK 25:
    /// `findResource(mn, name)`), never the class path's or another module's
    /// copy (`L3W96PlatformModuleResource` row `sql-other-module`), and its
    /// module's `module-info.class` (`L3W100ModuleInfoByModule`).
    #[test]
    fn i105_named_module_class_resource_is_the_modules_own() {
        let mut ctx = mock_ctx();
        ctx.set_resource("java/lang/Object.class", b"cafe".to_vec());
        ctx.set_resource("java/sql/Date.class", b"babe".to_vec());
        let date = ctx.ensure_class_initialized("java/sql/Date").unwrap();
        let object = ctx.ensure_class_initialized("java/lang/Object").unwrap();
        let date_mirror = make_class_mirror_with_package(&mut ctx, date.as_u32(), "java/sql/Date");
        let object_mirror =
            make_class_mirror_with_package(&mut ctx, object.as_u32(), "java/lang/Object");
        let ask = |ctx: &mut crate::test_utils::MockNativeContext,
                   mirror: ObjectRef,
                   name: &str,
                   url: bool| {
            let name = ctx.create_string_uninterned(name);
            let args = [Value::Object(Some(mirror)), Value::Object(Some(name))];
            let r = if url {
                native_class_get_resource(ctx, &args)
            } else {
                native_class_get_resource_as_stream(ctx, &args)
            };
            matches!(r.unwrap(), Some(Value::Object(Some(_))))
        };
        // No image scripted: the old class-path answer (the control).
        assert!(ask(&mut ctx, date_mirror, "/java/lang/Object.class", true));
        ctx.set_module_image(
            &[(date, "java.sql"), (object, "java.base")],
            &["java.base", "java.sql"],
            &[
                ("java/lang/Object.class", "jrt:/java.base/java/lang/Object.class"),
                ("java/sql/Date.class", "jrt:/java.sql/java/sql/Date.class"),
            ],
        );
        assert!(!ask(&mut ctx, date_mirror, "/java/lang/Object.class", true));
        assert!(!ask(&mut ctx, date_mirror, "/java/lang/Object.class", false));
        assert!(ask(&mut ctx, date_mirror, "Date.class", true));
        assert!(ask(&mut ctx, object_mirror, "/module-info.class", true));
        // Relative: `java/lang/module-info.class`, which no module holds.
        assert!(!ask(&mut ctx, object_mirror, "module-info.class", true));
    }

