    #[test]
    fn g2_collect_public_methods_skips_object_methods_for_interface() {
        // Test that collect_public_methods (backing Class.getMethods())
        // does NOT walk Object's public methods when the entry class is
        // an interface. Real JDK semantics вЂ” see
        // `Class.privateGetPublicMethods()` source for the
        // `isInterface() ? null : getSuperclass()` pattern.
        let mut ctx = mock_ctx();
        let object_cid = ctx
            .ensure_class_initialized("java/lang/Object")
            .expect("ensure Object");
        // Give Object some 0-arg public methods so we'd see them if
        // walked.
        let object_methods = vec![
            MethodMetadata {
                name: "toString".to_string(),
                descriptor: "()Ljava/lang/String;".to_string(),
                access_flags: 0x01,
                declaring_class_id: object_cid,
                exceptions: Vec::new(),
                signature: None,
            },
            MethodMetadata {
                name: "hashCode".to_string(),
                descriptor: "()I".to_string(),
                access_flags: 0x01,
                declaring_class_id: object_cid,
                exceptions: Vec::new(),
                signature: None,
            },
        ];
        ctx.set_declared_methods(object_cid, object_methods);

        // Interface declaring just one method.
        let iface_cid = ctx
            .ensure_class_initialized("com/example/IFace")
            .expect("ensure IFace");
        let iface_methods = vec![MethodMetadata {
            name: "doIt".to_string(),
            descriptor: "(I)I".to_string(),
            access_flags: 0x401, // ACC_PUBLIC|ACC_ABSTRACT
            declaring_class_id: iface_cid,
            exceptions: Vec::new(),
            signature: None,
        }];
        ctx.set_declared_methods(iface_cid, iface_methods);
        ctx.set_superclass(iface_cid, object_cid);
        ctx.set_is_interface(iface_cid, true);

        let methods = collect_public_methods(&mut ctx, iface_cid).unwrap();
        // Only `doIt` from the interface вЂ” Object methods are skipped.
        let n = ctx.array_length(methods);
        assert_eq!(
            n,
            1,
            "G2: collect_public_methods on an interface must skip Object's superclass methods (got {} methods)",
            n,
        );
    }

    #[test]
    fn get_methods_shadows_class_and_interface_overrides_without_losing_overloads() {
        // Regression for Spring DisposableBeanAdapter destroy-method lookup.
        // A concrete class's close() must hide both its superclass and
        // interface copies, while two real shutdown overloads remain visible.
        let mut ctx = mock_ctx();
        let parent = ctx
            .ensure_class_initialized("com/example/Parent")
            .expect("ensure Parent");
        let child = ctx
            .ensure_class_initialized("com/example/Child")
            .expect("ensure Child");
        let iface = ctx
            .ensure_class_initialized("com/example/Shutdownable")
            .expect("ensure Shutdownable");
        ctx.set_is_interface(iface, true);
        ctx.set_superclass(child, parent);
        ctx.set_interfaces(child, vec![iface]);

        let method = |name: &str, descriptor: &str, declaring_class_id| MethodMetadata {
            name: name.to_string(),
            descriptor: descriptor.to_string(),
            access_flags: 0x0001,
            declaring_class_id,
            exceptions: Vec::new(),
            signature: None,
        };
        ctx.set_declared_methods(
            parent,
            vec![
                method("close", "()V", parent),
                method("shutdown", "()V", parent),
                method("shutdown", "(J)V", parent),
            ],
        );
        ctx.set_declared_methods(child, vec![method("close", "()V", child)]);
        ctx.set_declared_methods(
            iface,
            vec![
                method("close", "()V", iface),
                method("shutdown", "()V", iface),
                method("shutdown", "(J)V", iface),
            ],
        );

        let methods = collect_public_methods(&mut ctx, child).unwrap();
        let mut closes = Vec::new();
        let mut shutdowns = Vec::new();
        for i in 0..ctx.array_length(methods) {
            let method_obj = match ctx.get_array_element(methods, i) {
                Value::Object(Some(obj)) => obj,
                other => panic!("expected Method object at index {i}, got {other:?}"),
            };
            let name = match method_name_value(&ctx, method_obj) {
                Value::Object(Some(name)) => ctx.read_string(name).unwrap_or_default(),
                other => panic!("Method.name must be a String, got {other:?}"),
            };
            if name == "close" {
                closes.push(method_obj);
            } else if name == "shutdown" {
                shutdowns.push(method_obj);
            }
        }

        assert_eq!(
            closes.len(),
            1,
            "getMethods must expose one overridden close()"
        );
        let declaring_name = |method_obj| match method_clazz_value(&ctx, method_obj) {
            Value::Object(Some(mirror)) => mirror_class_name(&ctx, mirror).unwrap_or_default(),
            other => panic!("Method.clazz must be a Class mirror, got {other:?}"),
        };
        assert_eq!(
            declaring_name(closes[0]),
            "com/example/Child",
            "the leaf-class close() must win"
        );
        assert_eq!(
            shutdowns.len(),
            2,
            "the two real shutdown overloads must remain, without interface duplicates"
        );
        for shutdown in shutdowns {
            assert_eq!(
                declaring_name(shutdown),
                "com/example/Parent",
                "an inherited class method must shadow the same interface method"
            );
        }
    }

    #[test]
    fn g2_synthetic_decls_for_method_class_does_not_clobber_real_class_methods() {
        // Real-class methods take precedence вЂ” same invariant as F2's
        // ClassLoader test, applied to Method.
        let mut ctx = mock_ctx();
        let m_cid = ctx
            .ensure_class_initialized("java/lang/reflect/Method")
            .expect("mock ensure_class_initialized must succeed");

        // Inject "real" `invoke` declaration with distinct flags.
        let real_meta = MethodMetadata {
            name: "invoke".to_string(),
            descriptor: "(Ljava/lang/Object;[Ljava/lang/Object;)Ljava/lang/Object;".to_string(),
            access_flags: 0x09, // ACC_PUBLIC|ACC_STATIC, distinct from synthetic 0x81
            declaring_class_id: m_cid,
            exceptions: Vec::new(),
            signature: None,
        };
        ctx.set_declared_methods(m_cid, vec![real_meta]);

        let merged = declared_methods_with_synthetic(&ctx, m_cid);
        let invokes: Vec<&MethodMetadata> = merged
            .iter()
            .filter(|m| {
                m.name == "invoke"
                    && m.descriptor == "(Ljava/lang/Object;[Ljava/lang/Object;)Ljava/lang/Object;"
            })
            .collect();
        assert_eq!(
            invokes.len(),
            1,
            "G2: real-class invoke must not be duplicated by synthetic augmentation",
        );
        assert_eq!(
            invokes[0].access_flags, 0x09,
            "G2: real-class flags must win over synthetic flags",
        );
    }

